window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_032"]={"n":"林光","dyn":"明","poems":[{"t":"浴日亭次东坡韵","f":"七言律诗","c":["落落星辰没远天，腾腾金浪满黄湾。","无时可滞升空日，万撼难摇抱海山。","天远未须扶赤手，霞红不觉上苍颜。","须知造化烦谁力，无限阳和宇宙间。"]},{"t":"扶胥书事借东坡韵","f":"七言律诗","c":["扶胥几许频声意，黄木空流水一湾。","何处此杯偏放手，百年青眼细看山。","浮生向老输钳口，黑发逢秋未腆颜。","多谢波罗数株树，也能相候水云间。"]},{"t":"漫兴","f":"五言绝句","c":["长薄消晨烟，返照啼幽鸟。","飘然过片云，寒山青了了。"]},{"t":"过同安谒余忠宣公祠","f":"七言律诗","c":["同安郡前舟不进，忠宣祠下首频回。","野云冥冥天地改，孤城落落心肝摧。","长江风声自旦暮，青冢岁月老崔嵬。","树根久坐兴长叹，山禽百种将予哀。"]},{"t":"登戏马台","f":"五言古诗","c":["逍逍步山坡，野花发幽香。","累累多荒坟，行矣心独伤。","偶逢道中人，语我西楚王。","戏马留遗踪，遥遥指前冈。","揽衣尽馀情，徘徊白云乡。","群山招欲来，百感易中肠。","如何豺虎心，一视空群羊。","智术日相高，成败休论量。","谁能揭日月，徒尔假隙光。","我悲千载人，落落空荒唐。"]},{"t":"过鄱阳湖","f":"五言律诗","c":["滚滚浪头白，飘飘舟子轻。","江吞庐阜足，云隔豫章城。","风水行秋气，乾坤老客声。","旧游瞻白鹿，百种起幽情。"]},{"t":"吉水别袁德纯侍御","f":"五言律诗","c":["风叶鸣乌桕，秋云起野烟。","蹉跎别君意，迢递上江船。","何处无薇蕨，斑衣且岁年。","斜阳忽相失，凝睇入螺川。"]},{"t":"宿明月寺","f":"五言律诗","c":["杖藜投野寺，步月入山棱。","方丈明孤烛，袈裟谒两僧。","厨烟分异茗，炉火燃香藤。","近识罗浮面，抟空一老鹏。"]},{"t":"宿罗浮冲虚观","f":"五言律诗","c":["山灵久相候，今夜宿冲虚。","三岛天分处，双楼月到初。","已觉非人世，端堪卜此居。","豫章曾住处，万古一潸如。"]},{"t":"冲虚观遗羽士","f":"五言律诗","c":["铁桥空在望，胜事几能同。","此地堪投足，吾生易转蓬。","剑光飞魍魉，云气隔崆峒。","欲把长生术，从头问葛洪。"]},{"t":"纪万梅书屋","f":"五言律诗","c":["蓬岛知何处，终南异此区。","林塘空怅怏，圜堵散抠趋。","夜照辜山月，春归误燕雏。","摩挲十年意，空看万梅图。"]},{"t":"寄族弟秉之","f":"五言律诗","c":["城市风声隔，林泉兴味新。","眼中端望汝，地下足宁亲。","黑发终成雪，青山岂负人。","升沉休更问，颜子一生贫。"]},{"t":"登圭峰二首 其一","f":"五言律诗","c":["两目何曾瞬，诸山总有缘。","跏趺临绝壑，独自听鸣泉。","炎暑方初伏，安期共老禅。","市廛无意绪，遥见上孤烟。"]},{"t":"登圭峰二首 其二","f":"七言律诗","c":["湖山万里曾开眼，此地还招我一来。","老寺棱棱栖古佛，洪泉隐隐作真雷。","垂观万状俱呈献，却叹浮生能几回。","何日会寻王子晋，乘槎东去问蓬莱。"]},{"t":"南海浴日亭","f":"七言律诗","c":["苍茫捣绝铜鼓声，风烟两袖云凝凝。","海天吞吐终未了，今古滚荡成阳精。","寒山万个揖光晕，残星几点将馀明。","南州女儿慵于起，不问明朝阴复晴。"]},{"t":"寓南海祠","f":"七言律诗","c":["祠庙星霜九百周，野人衰病久淹留。","乾坤息息藏真念，云水依依谢胜游。","布被梦恬南海月，绨袍坐老虎门秋。","殷勤拾贮波罗子，怕有行人一舣舟。"]},{"t":"别舍弟克明","f":"五言律诗","c":["不作宗元别，宗元别易悲。","瘦躯犹怯病，殇汝尚含思。","老眼看时态，殷忧入腑脾。","百年能骨肉，贫贱亦何辞。"]},{"t":"苦病","f":"古风","c":["二五有嘉惠，眇躯荷深仁。","默默百年情，隆隆四体恩。","璠玙思在匮，瓴甋嗟流尘。","伤足在深想，垂堂屡逡巡。","胡乃颠沛中，灾祸兴膂?。","飘忽变故素，沈困在昏晨。","万窍藏阴风，四肢成卧轮。","焚蒸伏盲热，旦夕如环循。","累累莫支吾，生虑谢伊人。","两睫竟不交，八邪若相新。","念攒水菽老，忧积糟糠贫。","遗药饮孰疑，殷意沃且频。","垢含思一濯，屈永作恒伸。","三住秉躯要，百脉讶调驯。","一点终不昧，耿然贯苍旻。","形骸端可外，陶铸付大均。","忽忽岁时易，一笑回阳春。"]},{"t":"示诸生","f":"五言律诗","c":["张皇成废弛，隐约见精英。","鲁叟高林放，齐侯内晏婴。","谁能留白日，吾甚厌虚名。","花鸟娇临屋，春杯愧独醒。"]},{"t":"山行","f":"七言律诗","c":["白帽欹蒙一敝裘，独乘羸马步山丘。","春风面面天难老，溟海恢恢地亦浮。","阅世不劳均置足，逃名也欲习科头。","红尘断隔清湖洞，云鹤千峰任去留。"]},{"t":"罗浮归次石斋先生韵二首 其一","f":"五言律诗","c":["悬崖难置足，却顾几淹留。","草草淩晨发，依依入暝投。","年华更物候，世味白人头。","昨夜霜天月，梅香尚暗浮。"]},{"t":"罗浮归次石斋先生韵二首 其二","f":"五言律诗","c":["看云遭鹿过，弄水见龙留。","宝聚光须掩，声凡律岂投。","毫毛即天宇，泰华亦针头。","道眼无遗照，吾言愧浪浮。"]},{"t":"送戴志达举人还莆田","f":"五言古诗","c":["长日鸟声歇，山静若神守。","跫然闻足音，两马山之右。","开关询何客，拜此莆中友。","款款致衷素，历历未释口。","间关山路遥，会晤殊未偶。","呼童摘新豆，荐此榄山酒。","村酒那醉人，空歌拍铜斗。","浮生亦易了，白日好西走。","丈夫贵自树，穷通无好丑。","乾坤有常业，可大还可久。","千疮百孔馀，弥缝鲁中叟。","贤曹抱素资，策鞭良未后。","吾拙甘死穷，草木同枯朽。"]},{"t":"赠饮者","f":"七言绝句","c":["烂熳花前醉未休，漆园襟度晋风流。","芳菲已夺游人魄，入耳莺声可自由。"]},{"t":"答秉之","f":"七言绝句","c":["曾贺微阳一点回，梦中消息亦胚胎。","千红万紫今何若，莫负春声五夜雷。"]},{"t":"提学佥宪胡希仁先生访榄山留诗为识依韵奉答三首 其一","f":"七言绝句","c":["野云相逐惯披衣，梦断丹青亦掩扉。","忽枉烟霞一回首，令人空念十年非。"]},{"t":"提学佥宪胡希仁先生访榄山留诗为识依韵奉答三首 其二","f":"七言绝句","c":["不薄柴桑驾不回，村醪满引兴悠哉。","含情未尽东周话，云合乌巾父老来。"]},{"t":"提学佥宪胡希仁先生访榄山留诗为识依韵奉答三首 其三","f":"七言绝句","c":["赤手争看拯陆沈，铎声遥振海云深。","空山老我应无用，谩听南风换楚音。"]},{"t":"乙未九月十四日登罗浮飞云顶","f":"七言律诗","c":["立立空青明返照，遥遥行迈了崔嵬。","身轻欲逐云飞去，机尽从知鸟不猜。","四际莫遮天活脱，百年何幸此徘徊。","褰衣细认经行处，知有游人取次来。"]},{"t":"赠别佥宪胡先生升宪副之浙东仍提学三首 其一","f":"五言律诗","c":["采采青蒲叶，采之南海边。","秋光不可象，吾意亦茫然。","楚楚成梧槚，殷殷正诵弦。","风声又于越，垂老话何年。"]},{"t":"赠别佥宪胡先生升宪副之浙东仍提学三首 其二","f":"五言律诗","c":["我爱清秋水，相看更濯沿。","中流坐天镜，两岸见人烟。","泛泛日将暮，迟迟舟不前。","高歌莫三叠，沙上有鸥眠。"]},{"t":"赠别佥宪胡先生升宪副之浙东仍提学三首 其三","f":"五言律诗","c":["一脉桐江水，西流是浙川。","谁云富春老，不管弄潮船。","祠庙今稀矣，登临亦洒然。","经过此停棹，留咏寄南天。"]},{"t":"宿曹溪寺","f":"七言律诗","c":["过尽黄茅入翠微，溪流掬饮试临矶。","大千僧礼唐师祖，数百年留古钵衣。","宝鸭睡熏香袅袅，琉璃倒照夜辉辉。","平生愧我耽幽赏，洗足投筇久未归。"]},{"t":"鞋山","f":"七言律诗","c":["五老峰前样逼真，星霜遗弃几千春。","印穿湖上一轮月，不踏人间半点尘。","流水有情终日洗，野花如绣逐年新。","未知一只今何在，欲向鄱阳问水神。"]},{"t":"题殿元罗一峰草亭","f":"七言律诗","c":["病来久谢乾坤劳，白板双扉安所遭。","千峰不管甲子老，万窍一任天风号。","麋鹿过门看个个，野翁遗药来忉忉。","还怜弟子甘寂寞，检书入夜烧松膏。"]},{"t":"赠庄孔易先生","f":"七言律诗","c":["乾坤双眼为谁好，风雅百年回此翁。","饭颗山前思感遇，石头城下未从容。","官贫果拙营妻子，才大还堪了化工。","江舸促归空忍泪，白头能得几相逢。"]},{"t":"舟发白沙次?步口留别饯送诸友","f":"七言律诗","c":["翠湿菰蒲两脚收，鲤鱼风起浪花浮。","山云不障江门月，烟水何辜客子舟。","万里行藏人可与，一樽倾倒我能留。","殷勤莫负今宵会，何处尘埃不白头。"]},{"t":"水心遗址","f":"五言律诗","c":["羽檄传呼日，夫君独此心。","风波无定在，草莽几消沈。","卓落山依旧，清泠水到今。","平生右忠义，斜日此登临。"]},{"t":"过秋江刘素彬宅","f":"五言律诗","c":["来寻一峰老，过此万山层。","岭海千年意，秋江两夜灯。","桑麻留细话，蓑笠自堪凭。","为报忘机者，南溟有钓罾。"]},{"t":"泷江谒六一公","f":"七言律诗","c":["总谓文章真可恃，泷江阡草亦离离。","闲来岁月看谁惜，老去青山是故知。","霄汉有情终晰历，尘埃何处不糠秕。","今朝匹马沙溪路，却怪荒塍枕断狮。"]},{"t":"双松","f":"七言绝句","c":["寒入千林竟不知，双青霄汉可胜奇。","秦封不染山无恙，却忆罗浮独看时。"]},{"t":"题罗一峰同春书屋","f":"七言律诗","c":["何处峰峦不借春，短篱疏竹亦堪贫。","从知宇宙无多事，不道清虚解绊人。","老去祇扶青竹杖，醉来忘裹白纶巾。","行囊亦有青精饭，知就何山更卜邻。"]},{"t":"毛氏西园","f":"七言律诗","c":["桑麻何地不宜春，潦倒谁拚一味贫。","南国疏慵来我马，东风消息付何人。","泉通万壑俱流玉，云到千山总着巾。","多少升沈眼前事，一樽休更谢比邻。"]},{"t":"题罗一峰正密堂","f":"五言律诗","c":["啼鸟缓催诗，先生杳默时。","烟霞终此念，魍魉动相窥。","忽忽千山合，垂垂两鬓丝。","抠衣二三子，莫厌北山薇。"]},{"t":"题宣和殿临韩干马","f":"七言绝句","c":["天闲十二锁春阴，消得夷途万里心。","迢递岂须烦伯乐，东风芳草自千林。"]},{"t":"富田谒文丞相","f":"七言律诗","c":["云水相看数百峰，富田蓑笠又从容。","湖山何处非男子，宇宙常堪着此翁。","祠庙星霜几草莽，大家门户总春风。","凭谁细话兴亡事，烟雨霏微起暮钟。"]},{"t":"芗城书屋","f":"七言律诗","c":["买就风光野水滨，九衢尘里断知闻。","残编不尽千年意，蔀屋难消六合春。","短发丝丝观物变，青山冉冉为谁新。","夫君欲了闲滋味，须就罗浮卖卜人。"]},{"t":"云庄","f":"七言律诗","c":["云恋空山拥敝庐，不妨垂白在樵渔。","尘埃满眼成何事，舒卷看渠只自如。","沙径晚晴归独鹤，翠屏春老步轻裾。","数家烟火村南路，不似长安多马车。"]},{"t":"泷崖","f":"七言绝句","c":["索翠沿流老未休，青山面面水悠悠。","诸孙不解争梨栗，赢得金牛一点头。"]},{"t":"东墅","f":"七言绝句","c":["门外青山自不群，杖藜消得几回春。","状元一饭谋仍拙，若个诸郎有几人。"]},{"t":"游玉笥山","f":"五言律诗","c":["群玉隐天城，三春萃客星。","东风双袖暖，晴日百花明。","云水心偏远，烟霞梦未醒。","千峰吾欲老，长笑指东溟。"]},{"t":"留别罗一峰暨吉淦诸友","f":"七言律诗","c":["送送江村欲暮春，北风寒雨为谁频。","春杯且共消红烛，身事无端祇白云。","伏枕流年看佩剑，推篷入夜数星辰。","不知千里东吴路，云鹤相参有几人。"]},{"t":"豫章怀罗一峰","f":"七言律诗","c":["握手巴丘别一峰，洪城今雨又谁同。","滕王阁畔波涛远，孺子亭前春思浓。","总把升沈供冷眼，恒拚潦倒醉东风。","知他南浦桥头水，曾载游人月几篷。"]},{"t":"宿马祖寺二首 其一","f":"七言绝句","c":["眼底峰峦动几千，青山白帽任翛然。","今宵马祖跏趺处，说破寒岩一线天。"]},{"t":"宿马祖寺二首 其二","f":"七言绝句","c":["悬崖一枕傍云楼，入夜珠泉洒未休。","几曲画眉天欲曙，半钩残月在岩头。"]},{"t":"鹅湖谒四贤祠二首 其一","f":"七言律诗","c":["天留一会在乾坤，忽忽于今迹已陈。","啼鸟有情空认我，青山无语欲留人。","泉因到石声终别，棋或旁观着亦神。","独立苍茫几回首，白云依旧满山春。"]},{"t":"鹅湖谒四贤祠二首 其二","f":"五言古诗","c":["晨兴发铅溪，珠露凝未了。","丰茸忽升长，生意知多少。","低头谢九崖，巧语留双鸟。","遥遥见鹅湖，冉冉削天峭。","肩舆度远岑，拂袖穿林杪。","空谷春光回，曲径繁花绕。","盎盎载春怀，超超腾物表。","行迈入招提，新篁森窈窕。","颙然仰哲深，俯拜香风袅。","圣途久荆榛，盲聋昧昏晓。","嚣扰日沈浮，孰为张幽渺。","区区三四老，属意苦不小。","我来欲何言，万状俱料悄。","回溪弄活流，白月生层峤。"]},{"t":"峰顶寺","f":"七言绝句","c":["数亩畬田列小城，人间天上果分明。","金牛逸老耽幽赏，何处逢人一寄声。"]},{"t":"九崖","f":"七言绝句","c":["红石苍田果是佳，一层山隔一层崖。","先生有意看阳九，掷却微官任素怀。"]},{"t":"南岩寺","f":"七言律诗","c":["三级五级步纡回，千山万山招欲来。","悬岩一滴古今雨，香茗旋入烟霞杯。","啼鸟不知白日午，繁花却笑深春回。","招提几点淋漓墨，洒向东风万竹堆。"]},{"t":"游杭州西湖诸山","f":"七言律诗","c":["戴胜声中绿渐匀，东吴眼界一时新。","丹青不道能来我，山水依然是故人。","洒洒尚沾三月雨，腾腾小酌五湖春。","六桥花柳都如许，留得中原一岳坟。"]},{"t":"酌虎跑泉","f":"五言律诗","c":["东吴留此水，今日酌山瓢。","病骨含秋露，灵根长夜苗。","吴儿供戏剧，释子藉烹烧。","导引源流去，清波洗六桥。"]},{"t":"虎跑寺与袁德纯明府对饮","f":"七言律诗","c":["君亦逢难我亦难，十年天遣两相看。","折腰事在仓皇际，歌凤人过顷刻间。","元雾有情埋色豹，白云无计别青山。","松阴小酌休辞醉，明月尘氛控马鞍。"]},{"t":"题山间林下卷","f":"七言绝句","c":["红尘紫陌难容足，树脚云根好借眠。","几个莺儿醒午梦，一杯香茗虎跑泉。"]},{"t":"端午寓虎跑寺胡宪副来馈","f":"五言律诗","c":["忽忽临重午，无营得自娱。","依僧谢荤酒，沿涧羡菖蒲。","时节催人世，风光控越吴。","又劳胡宪府，一价过西湖。"]},{"t":"竹隐","f":"七言律诗","c":["飕飕几个便成林，兴渐浓时绿渐深。","春事祇酣桃柳梦，此君那得市廛心。","但教色色堪留凤，不怕炎炎解铄金。","试把一竿来赠我，五湖风月足追寻。"]},{"t":"和宪副胡复庵重访虎跑行寓二首 其一","f":"五言律诗","c":["倦扶方竹杖，渴饮虎跑泉。","云水无穷尽，山河自引牵。","百年甘一点，万里睹回沿。","屈指罗浮下，翻疑抱犊眠。"]},{"t":"和宪副胡复庵重访虎跑行寓二首 其二","f":"五言律诗","c":["井花消得暑，我爱弄清泉。","谷树千株立，岩云百丈牵。","南熏来不灭，幽涧可穷沿。","暂解黄金带，先生解借眠。"]},{"t":"题方童子卷","f":"五言律诗","c":["少小何曾忽，春风见两诗。","能寻白沙意，可了互乡疑。","进履还堪试，挥毫亦不辞。","骎骎来半百，吾眼独斯儿。"]},{"t":"游天平山","f":"七言律诗","c":["行行忽远阖闾城，野寺经多不记名。","吴郡声光还范老，好山奇古到天平。","秋林返照谁能舍，云水之人眼自明。","却笑方袍僧一个，瓦盘趺坐采新菱。"]},{"t":"登姑苏台过上方转石湖小酌","f":"七言律诗","c":["远树苍苍佛塔孤，姑苏台上望姑苏。","塘船载酒穷秋渚，芦簟铺云醉石湖。","一镜光芒连睥睨，九龙飞舞下平芜。","夫差山水依然在，谁信西施误得吴。"]},{"t":"秋野","f":"五言绝句","c":["远水一抹碧，疏林几树红。","苍茫吟不了，诗在夕阳中。"]},{"t":"酌惠山泉","f":"七言律诗","c":["曾向慈山久借眠，虎跑之水水之贤。","还移杖屦来尝此，一饮烟云便洒然。","品第人多尊陆子，秤评吾欲遍周天。","香茶白饭逢僧话，丁酉中秋月渐圆。"]},{"t":"寓惠泉僧舍","f":"七言绝句","c":["日日呼童汲活池，九龙峰下缓归期。","无胶可变漕渠浊，翻笑塘船忍渴时。"]},{"t":"客中重九日","f":"七言律诗","c":["去年今日却辞家，今日今年兴未涯。","细雨端能妨令节，乌巾元不负黄花。","禽鱼可乐非关酒，星汉无缘枉问槎。","万里烟霞供一瞬，懒将双足画添蛇。"]},{"t":"游定山寺","f":"七言律诗","c":["浦子城边一寺佳，又扶青玉索丹崖。","寻常云水都吾辈，如此江山有木斋。","花草总堪供潦倒，烟霞元不待安排。","悠然又见钟山面，不信尧夫浪打乖。"]},{"t":"真珠泉","f":"七言律诗","c":["每每穷源爱绝清，今朝老眼又分明。","偶来浦口尝真味，始觉中泠久擅名。","天汉定应通此窍，山灵端亦候先生。","尘沙不乱天光在，消得狂言作重轻。"]},{"t":"项羽庙二首 其一","f":"七言律诗","c":["一语韩生似可听，将军抵死恋彭城。","嬴秦可问惟真主，赤子来归岂甲兵。","叱吒风雷惊海内，如斯汉子亦人英。","我来唤醒输赢梦，门外长江一带横。"]},{"t":"项羽庙二首 其二","f":"七言律诗","c":["商山人亦解歌讴，识破些儿可便休。","心胆果甘秦虎豹，丹青宁作汉伊周。","一时草莽谈今日，千古云山自九州。","欲把升沈问遗老，白云西去水东流。"]},{"t":"浴香淋汤泉","f":"七言律诗","c":["三三两两暮春前，点也曾蒙一喟然。","拨破烟云来弄月，却疑尘骨换流泉。","薰蒸此气真堪爱，感应之机可浪言。","翠竹疏松回晚照，暖风吹我过前川。"]},{"t":"者落道中","f":"七言律诗","c":["供世从知力果难，敢将双鬓只人寰。","青袍白马罗浮思，暖日和风者落山。","几处村庄粳米酒，一般乡语笑谈间。","从前枉读三千卷，争似香淋一浴还。"]},{"t":"游龙洞","f":"七言律诗","c":["奇观万状伟吾前，立马岩头一愕然。","天秘地藏人几见，神施鬼设我难言。","小儿造化真精巧，三岛蓬莱尺浪传。","更著数行庄老笔，倩谁移去对南川。"]},{"t":"留别庄木斋四首 其一","f":"七言律诗","c":["忽忽江南春信近，野夫高兴傍梅关。","欲吟不了山随在，去住无心云共闲。","岭峤霞烟堪我老，罗浮花鸟不人间。","东西南北无拘碍，敢向先生便作难。"]},{"t":"留别庄木斋四首 其二","f":"七言律诗","c":["草铺和暖村醪熟，欲别踟蹰话更投。","白日长江能万里，深冬行子且孤舟。","琅琊岂吝青藜杖，采石宁无旧酒流。","白首爱君知未了，鄱阳五老久凝眸。"]},{"t":"留别庄木斋四首 其三","f":"七言律诗","c":["江雨霏霏白不收，阻双行脚出无由。","北风肯为吹成雪，明日还须更倚楼。","四壁一灯深此念，千年双鬓总嫌秋。","江涛满眼成深阻，霁景和风得个舟。"]},{"t":"留别庄木斋四首 其四","f":"七言律诗","c":["眼底风花入短章，老怀终不为诗狂。","江村迟暮逢今雨，天地精神看点阳。","永日空山丝发短，孤灯残漏世几忘。","卧林三月春光满，万紫千红乞寄将。"]},{"t":"卧林亭","f":"七言律诗","c":["洗足投筇试小床，儿童争讶野夫狂。","江声几夜深杨子，木榻千年惜豫章。","风雨他时劳梦寐，星辰垂老问行藏。","木棉被暖疏更断，听得邻鸡报日光。"]},{"t":"和木斋雨中宿徐伯淳宅与姚润华夜话","f":"五言律诗","c":["飘拂变故素，踟蹰断远寻。","朔风号夜永，冬酒著人深。","云有无穷态，天留不死心。","暂须回艇子，江面缔重阴。"]},{"t":"白下怀木斋","f":"七言律诗","c":["独自歌吟独自酬，芳蘋采采倦仍休。","山光浦口难交睫，风色新河尚舣舟。","万里招邀椰子酒，几宵颠倒木绵裘。","鸟巾小落频看镜，莫是今朝白了头。"]},{"t":"江宁留别徐伯淳","f":"七言绝句","c":["仓皇竖子急招呼，岂识西风是逆途。","雨脚不收江浪白，野夫今夜伯淳庐。"]},{"t":"发杨子汪","f":"七言律诗","c":["鹦鹉洲前豁两眸，长风竟日几曾休。","轻帆上水奔千骑，白浪吞江吼万牛。","南北恢恢真自得，乾坤纳纳壮欺游。","苍茫采石长庚子，须尔还来共倡酬。"]},{"t":"宿西梁","f":"五言律诗","c":["赛神馀十酌，舟子谩招邀。","深夜人犹语，孤灯雪自飘。","西梁山欲拔，阴沴气仍骄。","伏枕惟深汊，阴晴阅改朝。"]},{"t":"江行","f":"七言律诗","c":["沙边不见有眠鸥，何处芦花著钓舟。","江浪不须频骇目，野人曾亦久科头。","垂堂我愧千金子，积雪山成万玉楼。","翘首巨卢促归棹，故园桃李不胜秋。"]},{"t":"渔者","f":"七言绝句","c":["风急江深少着篙，夕阳回首谩波涛。","鳊鳇入手看能几，怪得渠侬索价高。"]},{"t":"吉阳避风示舍弟克明","f":"七言律诗","c":["江豚吹浪杂蛟鼍，白苇黄芦望更多。","短棹虽能忙此日，长江何得不风波。","星霜历历双蓬鬓，天地寥寥一浩歌。","弟倡兄酬能放手，万回吾敢怨诗魔。"]},{"t":"再用前韵答克明","f":"七言律诗","c":["挂席冬冬谩击鼍，长风能送可须多。","青山更有森如玉，老眼还能碧似波。","横槊他年空自伟，饮牛何处枉悲歌。","涂泥久蛰精神富，天地休嗟逆境魔。"]},{"t":"吉阳发舟晚抵鄱阳风涛汹涌","f":"七言律诗","c":["万顷波涛走巨艘，赓酬不暇骇吾曹。","天关地轴疑交转，河伯风师莫太劳。","气会江湖何振拔，势吞吴楚自呼号。","旷然心目增多少，俯仰斯游亦伟遭。"]},{"t":"望匡庐","f":"七言律诗","c":["五老皤然出逶迤，知君相候亦多时。","十年不尽今朝意，数首空留点画诗。","秋月春花谁合主，丹房翠壁醉何疑。","扁舟左蠡频回首，云掩千年白鹿祠。"]},{"t":"筠州鞭春日偶成","f":"七言律诗","c":["阛阓童儿笑语频，昨闻官府又迎春。","好山在处都宜我，淑气今朝已着人。","鸾镜未应羞黑发，鸠藤聊此领间身。","阿谁更有狂如我，共向筠州一问津。"]},{"t":"立春日游碧落山","f":"七言律诗","c":["何处山光到酒频，今朝碧落始逢春。","穿云返照留醒眼，饱雪疏松煞爱人。","二老不饶惟白发，千金难买是闲身。","自歌自笑扶青玉，来用来休更锦津。"]},{"t":"答陈贰教","f":"七言律诗","c":["咄咄书空数岁频，梅花四十指头春。","膏肓泉石终惭我，大雅声光却望人。","木榻可辜千里梦，绨袍能恋百年身。","朝来听得筠人语，流水桃花有别津。"]},{"t":"除夕前三日阅戊戌历","f":"七言律诗","c":["骄阴断送过冬频，黄纸新开得早春。","甲子巧当元日脚，屠酥偏待少年人。","杖藜俯仰难供世，行几跏趺称病身。","料理太平堪击壤，鹃声何敢到天津。"]},{"t":"留别子颖","f":"七言律诗","c":["不须黄白语繁频，且共斟量曲米春。","锦水谢虚西一席，罗浮远饷独归人。","泥途不厌经冬蛰，泉石何疑向老身。","尽任龙钟深取醉，夕阳回首杳行津。"]},{"t":"冷庵为陈粹之佥宪","f":"七言律诗","c":["老蛰安冬不露辉，此庵宁与此翁违。","三更白月常留照，九夏晴霜也自飞。","何处炎炎堪炙手，此中默默已无机。","宜春短褐还飘洒，曝背何妨爱晚晖。"]},{"t":"题画二首 其一","f":"七言绝句","c":["云尽山空独远寻，一桐难觅是知音。","行行更过长桥去，耳不聋人在碧岑。"]},{"t":"题画二首 其二","f":"七言绝句","c":["绿树森森野照明，荷风荡漾布帆轻。","幽轩坐睡非难觉，只欠黄鹂三两声。"]},{"t":"相如题桥","f":"七言绝句","c":["会得真虚不是虚，乾坤随处总如如。","凭谁寄语题桥子，何必还过驷马车。"]},{"t":"题渔图","f":"五言绝句","c":["渔翁方手网，渔子就青波。","脱或吞舟过，看渠又若何。"]},{"t":"谢陈粹之佥宪惠语类欧文唐诗品汇","f":"七言律诗","c":["稠叠颁分几案盈，穷儿暴富可胜情。","滥觞此日嗟文字，老眼馀谁敢秤评。","博约的知遵鲁叟，疏慵深恐负先生。","石亭一瓣当西席，便合低头拜使星。"]},{"t":"题画","f":"五言绝句","c":["瑰石怪而奇，古木秃而瘦。","翛然着此君，天地得三秀。"]},{"t":"登滕王阁","f":"七言律诗","c":["江南绝景闻童阁，四十年来此一登。","春及青山他自好，霜欺短发我何能。","三王伟迹人争壮，万里双眸此更凝。","野服岂须愁急雨，柳风吹面醉腾腾。"]},{"t":"溪山小景","f":"七言绝句","c":["门外青溪溪外山，逐云飞去逐云还。","打鱼烟艇休撑去，留载山僧一段闲。"]},{"t":"谢欧阳玘医时会头疮","f":"七言绝句","c":["白疥相将秃此童，佛头螺子碧丛丛。","今朝眼底看蝉蜕，谢得南昌七十翁。"]},{"t":"和祈大参致和将出巡阻雨见寄三首 其一","f":"七言绝句","c":["断送骄阴好是难，一春寒似一冬寒。","使君画舫须料理，万顷波涛正渺漫。"]},{"t":"和祈大参致和将出巡阻雨见寄三首 其二","f":"七言绝句","c":["千红万紫欲开难，终日斜斜雨雪寒。","安得晴无云一点，步随春水看弥漫。"]},{"t":"和祈大参致和将出巡阻雨见寄三首 其三","f":"七言绝句","c":["几许相逢欲话难，一樽还解辟春寒。","深杯莫厌罗浮味，千里云山易渺漫。"]},{"t":"苏公圃","f":"七言律诗","c":["潦倒烟霞得此身，一瓢吾敢怨吾贫。","又携东莞青藜玉，来吊南昌鬻屦人。","畦叶春深交翡翠，藕花风暖散茵陈。","缄书果解酬知己，青草王孙几度新。"]},{"t":"永新谭节妇","f":"七言律诗","c":["白刃前头叱一言，舅姑今得见黄泉。","皇天自解知人意，母子分明在血砖。","胡羯腥风吹海内，丈夫臣仆几城边。","寻常一妇网常击，万古精神尚凛然。"]},{"t":"谒徐孺子次石斋韵三首 其一","f":"七言律诗","c":["面面湖光水镜寒，一丘垂老足盘桓。","冥鸿阅世终辞缴，白刃临头几见冠。","南亩有情拚独力，西山无数共谁看。","故人谢得常留榻，三复应难露肺肝。"]},{"t":"谒徐孺子次石斋韵三首 其二","f":"七言律诗","c":["松竹摩挲对夕阳，东湖亭上吊荒亡。","清风南国千年在，片碣开元只眼光。","田野自能容此老，湖山终不爱名香。","焦头烂额支颠厦，陈窦何曾纪太常。"]},{"t":"谒徐孺子次石斋韵三首 其三","f":"七言律诗","c":["到处耕庸亦不悲，巢栖穴处尚谙时。","三秋异卉终难好，一柱颓波别有裨。","当宁叠能崇礼数，四山元亦托心知。","生刍迢递来今日，一瓣名香孺子祠。"]},{"t":"题蓝关拥马图","f":"七言律诗","c":["老凤孤鸣骇豕羵，元和无复别莸熏。","山堆碧玉前当马，天设琼林此送君。","精魄已开衡岳障，化机将变岭南云。","飘飘可是来湘子，兴丧而翁验片文。"]},{"t":"将谒徐孺子","f":"七言绝句","c":["百年湖海留双脚，每每思登孺子亭。","小酌几时逢好日，北风吹雨又冥冥。"]},{"t":"过陈国宾园亭","f":"七言绝句","c":["偶过东湖日未斜，满城谁是辟疆家。","寻常杯酒还来此，指点春风几树花。"]},{"t":"赏瑞香和杜醉老","f":"七言绝句","c":["春杯吾欲挽西江，况有天香傍玉缸。","醉眼换将醒眼看，题诗还得笔如杠。"]},{"t":"题幽贞四咏卷","f":"七言绝句","c":["走笔题诗每欲欢，九原情况和终难。","何人却有丹青手，写出幽贞卷上看。"]},{"t":"题西湖醉老卷","f":"七言绝句","c":["天地颓然一醉翁，眼拚花着耳拚聋。","却疑南浦频频酒，还记催诗入卷中。"]},{"t":"豫章留别陈粹之佥宪","f":"七言律诗","c":["石亭留滞两旬间，南浦西来面一湾。","又趁蒲帆投五岭，敢将藜杖薄西山。","寒风往往疑正雨，短发垂垂愧病颜。","谢得章江门外路，使君曾为几偷閒。"]},{"t":"刚峰","f":"七言律诗","c":["芗城放出千寻碧，鬼斧曾经百炼来。","历历星霜终不改，棱棱霄汉老崔嵬。","风云变态知何限，花草荣枯又几回。","目断罗浮峰四百，为渠天际重徘徊。"]},{"t":"清明五云阻风过萧氏庄","f":"七言律诗","c":["断阻狂风走逆沙，五云郊外步桑麻。","惊心惶恐滩头水，着眼清明节里花。","诗就带云眠野草，酒醒和叶嚼生茶。","行行不觉边廛市，失记村庄历几家。"]},{"t":"别梁光岳","f":"七言绝句","c":["舴艋长牵溯逆流，春风追送几濒头。","他年记取南安路，莫误今朝是广州。"]},{"t":"题画","f":"七言绝句","c":["老树交加叶半空，山禽各各岭东风。","披图指点春消息，欲为罗家一折中。"]},{"t":"盘窝观笋","f":"七言绝句","c":["苦竹惊看几笋抽，满前生意不曾休。","信知一部羲爻易，底用寻行数墨求。"]},{"t":"萧庄观盘鱼","f":"七言绝句","c":["洋洋相逐几鱼儿，盆里观来不似池。","万顷澄波清见底，南溟翻忆钓鳌时。"]},{"t":"醒庵","f":"七言绝句","c":["曲蘖生香满小糟，看君不饮果然高。","我亦如今醒不得，任教终日醉陶陶。"]},{"t":"上十八滩","f":"七言绝句","c":["逆境甘心不作难，南风终见北风还。","昨宵篷底茶园梦，今日扁舟十八滩。"]},{"t":"西隐寺","f":"七言律诗","c":["一樽随处弄云烟，点破沙门几许禅。","野服又临西隐寺，南风留得赣州船。","浮生未了空王梦，灌木仍开小洞天。","惆怅郁孤台上酒，不知何日更留连。"]},{"t":"望郁孤台","f":"七言律诗","c":["两河山势叠相催，突兀城头露翠堆。","木履可宜官府地，春风深负郁孤台。","双眸向老终嫌窄，笑口于今几浪开。","转盼又临清远峡，一樽留待上飞来。"]},{"t":"蒙泉书屋","f":"七言律诗","c":["引得清清抱小轩，沙泥不许混真源。","千峰精魄藏山腹，万斛珠玑喷石根。","育德频年深大象，濯缨满耳咏诸孙。","虎跑龙井都差别，肯向罗湖吝一言。"]},{"t":"和王半山韵十八首 覆叠题九首 其一","f":"五言律诗","c":["折腰辞长吏，结社许沙门。","宦海诸人溺，颓波一柱存。","桑麻春自满，蜂鸟日相喧。","恬却奔波梦，栖栖只故园。"]},{"t":"和王半山韵十八首 其二","f":"五言律诗","c":["柴桑归汲汲，幽思向谁言。","流水长随步，青山自绕门。","肩舆僧社月，草座野人樽。","指点重阳菊，丛丛又满园。"]},{"t":"和王半山韵十八首 其三","f":"五言律诗","c":["区区贪献玉，足刖枉沽裳。","且任横肱睡，何妨举世忘。","陶陶春酒后，洒洒竹风凉。","午梦醒香茗，扶藜过小冈。"]},{"t":"和王半山韵十八首 其四","f":"五言律诗","c":["是山都指点，绝景更搜寻。","敢道无佳似，终须遇赏音。","青精浇白水，短发付长吟。","红紫看无了，莺声又绿阴。"]},{"t":"和王半山韵十八首 其五","f":"五言律诗","c":["一泓凝不乱，独爱看真源。","白日人稀少，中年眼未昏。","葛蕉居士服，杖屦榄山村。","紫豆银茄种，如今灌渐繁。"]},{"t":"和王半山韵十八首 其六","f":"五言律诗","c":["疾风馀毁瓦，疏竹尚迎门。","贫识人情改，寒思士屋温。","一瓢终易足，四壁也难存。","浩荡春光满，何山不故园。"]},{"t":"和王半山韵十八首 其七","f":"五言律诗","c":["松阴横一枕，翻忆在扶胥。","铜鼓回春梦，波罗集异乌。","于今甘拙讷，不睡复何如。","九鼎传东汉，休云一钓扶。"]},{"t":"和王半山韵十八首 其八","f":"五言律诗","c":["潇洒东皋路，登临亦不时。","先生拚屡醉，花鸟任相怡。","翠带垂千柳，金梭掷一鹂。","踟蹰归路晚，凉月浸西陂。"]},{"t":"和王半山韵十八首 其九","f":"五言律诗","c":["清风时一洒，默坐听渔歌。","蚊蚋何曾炒，烟霞敢自多。","一竿持白月，万顷钓晴波。","兹事还堪领，将衣制芰荷。"]},{"t":"和王半山韵十八首 其十 怀古","f":"五言律诗","c":["瓶空无贮粟，松菊在名园。","秫酒浇时变，乌巾到老存。","北窗元自在，三径绝烦喧。","一任儿曹懒，清风自扫门。"]},{"t":"和王半山韵十八首 其十一","f":"五言律诗","c":["每每亲秋菊，欣欣涉晓园。","班荆罗父老，披褐倒杯樽。","春换青丝柳，山深白板门。","懒将贪睡息，屡屡向人言。"]},{"t":"和王半山韵十八首 其十二 歌眠","f":"五言律诗","c":["掩耳无多事，支颐就小床。","梦恬香篆细，酒醒布衾凉。","白月天留照，浮云世易忘。","仓皇那浪起，颠倒着衣裳。"]},{"t":"和王半山韵十八首 其十三 山行","f":"五言律诗","c":["藜杖何曾吝，浮云只自阴。","春花方蓓蕾，天地与歌吟。","自尔穷幽兴，何须问赏音。","钟期双耳孔，千古杳难寻。"]},{"t":"和王半山韵十八首 其十四 即事","f":"五言律诗","c":["山静人希到，春深花自繁。","鸠藤行处酒，烟火望中村。","偶尔逢耕叟，迟回话夕昏。","不知天壤内，何处是桃园。"]},{"t":"和王半山韵十八首 其十五 经故居","f":"五言律诗","c":["青藜时领步，偶过旧栖园。","梁燕语相认，春风迹尚存。","尧天终共覆，孔席不曾温。","贫病翻疑我，区区扫一门。"]},{"t":"和王半山韵十八首 其十六 昼寝","f":"五言律诗","c":["香醪堪日醉，伏枕免人扶。","白昼心无事，清贫病恪如。","沈沈甘朽木，忽忽走金乌。","役税均明府，门无炒吏胥。"]},{"t":"和王半山韵十八首 其十七 东皋","f":"五言律诗","c":["低回滕伞岭，怅望曲龙陂。","花气盈双袖，春声转数鹂。","老亲那作恶，稚子巧相怡。","尽日穷清赏，春光未暝时。"]},{"t":"和王半山韵十八首 其十八 露坐","f":"五言律诗","c":["滴露凝疏竹，香风递远荷。","科头南海月，绝耳虎门波。","僻地栖来惯，清宵得处多。","老怀凉不寐，听得采莲歌。"]},{"t":"题白沙节母受旌卷","f":"七言绝句","c":["总贺风声树一门，如斯母子白沙村。","却怜败壁寒帏下，多少贞婺欠此恩。"]},{"t":"偶书","f":"七言绝句","c":["贫极糟妻不怨煎，双亲菽水渐安然。","空山环堵秋光满，可值千金几觉眠。"]},{"t":"开户","f":"七言绝句","c":["云掩重关久不开，草深行径竹穿台。","山空夜静炉烟歇，且放中秋月又来。"]},{"t":"偶题","f":"七言绝句","c":["黄沙蚬子贱如泥，赤鲤青鲇价总低。","日饮两杯家酿熟，阁徐经史又山溪。"]},{"t":"伤竹三首 其一","f":"七言绝句","c":["嫩箨新移不耐吹，狂风拜舞久离披。","归来欲把墙高筑，不是嫌他冷眼窥。"]},{"t":"伤竹三首 其二","f":"七言绝句","c":["墙角风稍醉未醒，卷心虫叶瘦伶俜。","相看孰忍持斤斧，雨洒烟催不暂停。"]},{"t":"伤竹三首 其三","f":"七言绝句","c":["青青叶子是何藤，弱竹稍头散玉绳。","亦为先生添一赏，只愁风雨重加增。"]},{"t":"绝句三首 其一","f":"七言绝句","c":["童草歌喉按转新，深杯延醉日频频。","试留醒眼斜阳外，谁到离披不丧真。"]},{"t":"绝句三首 其二","f":"七言绝句","c":["寻行数墨祇昏尘，百涅千磨转畏人。","狂药浇狂还不谢，百年回首莫伤神。"]},{"t":"绝句三首 其三","f":"七言绝句","c":["半点阳和也自微，更呼残梦五更时。","芳菲已夺游人魄，曾咏他年一句诗。"]},{"t":"题扉二首 其一","f":"七言绝句","c":["童年俛仰及中年，一默真甘直万钱。","不觉春山又春鸟，疏松老竹作冬眠。"]},{"t":"题扉二首 其二","f":"七言绝句","c":["莺啼燕语自年年，春及侬家不用钱。","满户游丝花在网，醒时看竹倦时眠。"]},{"t":"谢石斋转惠辽东贺克恭黄门所寄高丽团领","f":"七言绝句","c":["一片丽云罩蚤春，不曾衣服只衣仁。","浴沂点也堪遗此，我愧幽栖懒动身。"]},{"t":"视决明","f":"七言绝句","c":["亲培种子向阶除，足不过门两月馀。","今日黄花开满树，可胜凝思念居诸。"]},{"t":"种芥","f":"七言绝句","c":["寸叶初移日未禁，根粘不觉雾烟深。","但须培灌休催促，一木如针且十寻。"]},{"t":"酌文举馈酒","f":"七言绝句","c":["石下樽封石上云，为渠澄淀到秋分。","谁将面米疑乡土，酿不差池总苾芬。"]},{"t":"看橙橘二首 其一","f":"七言绝句","c":["橙橘收功也十年，万千材器可消言。","可怜达曙喃喃子，责效区区便自前。"]},{"t":"看橙橘二首 其二","f":"七言绝句","c":["橙橘盈园到处基，一时牵惹盛如斯。","东山夜读西山和，风虎云龙未可知。"]},{"t":"灯蛾","f":"七言绝句","c":["焦头烂额死灯檠，衣袖频频拂不惊。","幽暗几多清寂处，不知何事苦投明。"]},{"t":"扶胥口二首 其一","f":"七言律诗","c":["海山无数尽龙腾，细浪和风不厌行。","谁解天边持北斗，试来此处酌南溟。","已知一勺同千顷，不把涔蹄笑洞庭。","安得常如银汉水，扁舟万里寂无声。"]},{"t":"扶胥口二首 其二","f":"七言律诗","c":["风疑飓母常犹豫，天入南溟本自清。","惯见黄湾红日上，忽催铜鼓远山明。","沈沈懒举烟霞笔，每每妨摇海岳精。","向老临流还袖手，极留青眼在长缨。"]},{"t":"望罗浮五首 其一","f":"七言律诗","c":["两年云水拚鸠杖，万里烟霞在指头。","尽道壶公能作怪，长疑此老久闲休。","蓬莱不省真谁见，造物如斯总秘留。","久雨掩人逢一霁，乾坤何处着双眸。"]},{"t":"望罗浮五首 其二","f":"七言律诗","c":["出门回首便临头，万玉中天翠欲流。","此老英华元自别，生民日用不知求。","群形散散终还聚，一脉沈沈远渐浮。","古镇峡围村九十，异香清结信何由。"]},{"t":"望罗浮五首 其三","f":"七言律诗","c":["深如南海厚罗浮，此气停储几百秋。","不与乖崖争华岳，懒寻关尹问青牛。","薪铺一路看燃火，律转三阳验发抽。","底事精光常浸润，不闻宣父降尼丘。"]},{"t":"望罗浮五首 其四","f":"七言律诗","c":["常须催促向罗浮，白首何人念此游。","瑞药灵苗堪备蓄，玉壶云液细封留。","双藜不谢飞云顶，一枕还寻见日楼。","试候赤龙腾巨海，光芒那只在南州。"]},{"t":"望罗浮五首 其五","f":"七言律诗","c":["岷峨一脉走南离，大庾回旋有此奇。","地设天留空甲子，云蒸雾拥到今时。","画难着笔端何语，眼总如星可尽窥。","回首铁桥忘旧路，秋光无限只题诗。"]},{"t":"朱都宪见游","f":"七言律诗","c":["披草香传竹径幽，午窗冬睡尚科头。","膏盲泉石终何取，麋鹿心情愧自由。","辗转更占前夜梦，踟蹰真被白云留。","橹声入夜难交睫，月子篷窗挂一钩。"]},{"t":"奉谢朱都宪诚庵先生","f":"七言律诗","c":["寻常折简也须来，敢道蓬门不浪开。","自古公卿贤可事，如今草莽愧非才。","神雷莫炒泥涂蛰，春信潜回琥珀杯。","俯仰乾坤无可谢，细留双眼看三台。"]},{"t":"玉笥罗浮亭","f":"七言律诗","c":["玉笥山前偶濯缨，罗浮亭子向君成。","未辜东莞人留诺，共爱金牛老结盟。","已付行藏同涧水，肯教魂梦愧山精。","铁桥四百峰前路，双眼须君更放青。"]},{"t":"挽罗一峰先生三首 其一","f":"七言律诗","c":["一代文星落两间，秋云黯黯夜漫漫。","孤舟握手人何在，五月来书墨未乾。","天地留情须挂剑，江湖去梦已凭棺。","千年目击先生面，还有网常一疏看。"]},{"t":"挽罗一峰先生三首 其二","f":"七言律诗","c":["进亦何惭退不疑，一峰盖世作男儿。","暂留翰苑非无地，却向金牛不尽期。","盎壤岂胜今日意，莺花又展去年诗。","婆娑一醉春风酒，尚忆芗城嘱别时。"]},{"t":"挽罗一峰先生三首 其三","f":"七言律诗","c":["莼鲈一箸尚休官，何处清风有状元。","梦破孤舟看野水，酒醒残月坐丘园。","寻常烟雨春芳歇，三四儿孙玉树存。","流水行云任分付，天无可怨我何言。"]},{"t":"辛丑得年四十三七月初见髭一茎白者走笔赋此","f":"七言律诗","c":["掀须犬子膝间横，笑指今朝白一茎。","衰此退之还差晚，寿过颜子竟何成。","寻常岁月消明镜，潦倒烟霞愧此生。","羡得青青檐外竹，向人无语不胜情。"]},{"t":"中秋袁藏用馈鱼写怀兼寄","f":"五言古诗","c":["白帝吝商飙，烦暑仍靡靡。","昨日山中归，倒卧西窗里。","开窗荫疏竹，炉烟灭复起。","宁知井屋下，索寞亦闲只。","提鲜来君池，白鲢兼赤鲤。","顷适尝新酿，浓香压酒子。","念兹赤壁携，浩然良有以。","今夕复何夕，中秋散霾滓。","开襟南川流，皓月照寒水。","吾欲泛扁舟，中流玩清泚。","思君君不来，弄丸空隐几。"]},{"t":"寓资福寺","f":"五言律诗","c":["塔飒招提景，春衫试苧麻。","吾那拘礼数，僧亦厌袈裟。","烟罩枇杷树，香传枸杞茶。","冬冬还到耳，晚鼓散官衙。"]},{"t":"题李乾伯掌教乃翁挽卷","f":"七言绝句","c":["壶公作怪亦多时，人物莆阳尽伟奇。","珍重先生何面目，孤儿觅我一题诗。"]},{"t":"银瓶阡","f":"七言律诗","c":["打起眠牛眼未醒，深松下马上银瓶。","翻疑造物劳施设，却怪青囊久秘灵。","天壤未乾孤子泪，烟霞叨贲石斋铭。","馀生百事看来左，何日相随到九冥。"]},{"t":"挥使安廷用访榄山留宿兼惠纸并猪榧子","f":"七言律诗","c":["荒畦移步及斜曛，回首肩舆出白云。","且向青天赊月色，何妨永夜款时军。","猪榧老母叨供茗，剡楮痴儿荷赏勤。","莫羡乖崖分华岳，麒麟阁上看殊勋。"]},{"t":"赠别李乾伯掌教","f":"七言律诗","c":["乱山千里谢官衙，岁暮江城理去槎。","木榻几回亲夜雨，马蹄曾不择烟霞，休辞别盏倾冬酒。","更探寒梅嗅晚花，欲别先生言不了，满川红树夕阳斜。"]},{"t":"将游三洲岩招同志二首 其一","f":"七言律诗","c":["留将百粤千年兴，偿却三洲一日游。","飞翰向逢梅御史，放吟今作白江州。","山光有分还招手，世计无端任转头。","何处元公轻着笔，不妨云水远搜求。"]},{"t":"将游三洲岩招同志二首 其二","f":"七言律诗","c":["紫府曾闻一洞幽，凝乘东舫作西游。","脚跟何日能千里，眼孔如今负九州。","山水猜排终我老，尘埃容易白人头。","贫家百事都难在，只有春光不用求。"]},{"t":"扶胥舟中借韦苏州西坡韵","f":"五言古诗","c":["东风挂蒲帆，推蓬聊骋望。","扶胥日模糊，虎门波浩荡。","归渔趁回流，急桨荡清漾。","团团立嘉树，点点罗远嶂。","对之若为情，颓然顺昭旷。","鸢鱼有真性，天地俦为量。"]},{"t":"鳌鱼抢宝石","f":"七言律诗","c":["破浪穿云涌石鲸，波心遥见瑞光呈。","那知物象俱含欲，只恐蛟龙见亦争。","舟楫频年渔子戏，风涛终日旅商情。","海门万里不归去，也欠僧繇一点睛。"]},{"t":"番禺泊舟二首 其一","f":"五言律诗","c":["边城无隙地，孤岛有僧居。","急桨过蛮叟，呼船问市鱼。","轻风醒宿酒，伏枕看残书。","断我登临兴，重云嶂碧虚。"]},{"t":"番禺泊舟二首 其二","f":"五言律诗","c":["暝色催正雨，腾腾海气蒸。","喧阗市井语，明灭夜船灯。","敛迹同渔父，投闲羡岛僧。","浮云思世计，种种不堪凭。"]},{"t":"铜船澳风二首 其一","f":"七言绝句","c":["苍梧亦进野人舟，怪得刚风故打头。","陈子贪泉留警句，明朝还作石门游。"]},{"t":"铜船澳风二首 其二","f":"七言绝句","c":["深港维舟我不宜，篙师力不胜风师。","骄阴冷送霏霏雨，明日阴晴未可知。"]},{"t":"经贪泉","f":"七言律诗","c":["沈香亭下向谁言，草草为心易百年。","安得还珠皆合浦，免教赤子怨贪泉。","山罝海网无遗策，惴耎肖翘亦损天。","好语戴歌吴刺史，清风吹过石门船。"]},{"t":"经贪泉和石斋","f":"五言律诗","c":["一点萃天灵，耿耿终未死。","惟人自昏浊，此水本清泚。","不戕羞恶根，自解嗔汝尔。","寄语往来人，冥冥有神鬼。"]},{"t":"三江晚泊二首 其一","f":"五言律诗","c":["敛桨三江寨，山寒日欲晡。","江流吞岭觜，岚气障天隅。","津吏何骄蹇，商船苦索需。","贪泉吾有赋，哦咏正区区。"]},{"t":"三江晚泊二首 其二","f":"五言律诗","c":["流逆频输楫，途生每问程。","篙师疲落日，津吏聒深更。","寨鼓沈沈点，潭星耿耿明。","梦魂今稍定，不怕岭猿惊。"]},{"t":"过横槎","f":"七言律诗","c":["春山春草绿将齐，更着春风日日吹。","老兴欲穷东广界，扁舟已造峡门西。","村墟亭午饶虾菜，古寨江边翳蒺藜。","稍待夕阳光倒蘸，笑临清泚弄玻瓈。"]},{"t":"羚羊峡","f":"七言律诗","c":["步步移舟步步新，东风催棹莫频频。","临江揖岫如迎我，过涘巅崖欲压人。","艰阻亦疑天设险，雄争颇觉地相嗔。","何谁貌得行边景，却为羚羊峡写真。"]},{"t":"忆嘉鱼","f":"七言绝句","c":["江深鱼板响连连，秃尾槎头不足怜。","惟问嘉鱼今出未，先生留得杖头钱。"]},{"t":"小湘峡","f":"七言绝句","c":["知是何山叠耸头，纵横直欲断江流。","看他峡内清清水，不到东溟未肯休。"]},{"t":"小湘峡叶生璧买鲜儗明日携游三洲岩诗以戏之","f":"七言律诗","c":["小网新提出峡门，船头泼剌见波翻。","霜刀且付饔人手，雪鲙看飞老瓦盘。","风景随拈皆落句，溪山到处可开樽。","何须屈指三洲路，不掷金钱负晚飧。"]},{"t":"宿禄步","f":"五言古诗","c":["行迈忽向夕，敛桨怯蛮少。","烟深禄步衙，风卷畬人烧。","横石喧江濑，缺月生夜照。","扣舷发清赏，孤鹤谐远嘹。","阳和布温春，魍魉伏深峤。","拥衾清不寐，默坐观吾妙。"]},{"t":"汲江子二首 其一","f":"五言绝句","c":["冉冉汲江子，江流几许深。","亦知泥滓浅，不得到波心。"]},{"t":"汲江子二首 其二","f":"五言绝句","c":["长绠疑惊浊，轻瓢谩撇新。","不知坭闪履，贪看过船人。"]},{"t":"观烧","f":"五言律诗","c":["气烈山将碎，声刚兽欲号。","獞猺疑逞雪，刘项讶争豪。","红焰摧林去，青烟逼汉高。","百虫惊蛰近，谁为激江涛。"]},{"t":"呼风","f":"七言绝句","c":["帆樯上下斗呼风，船尾船头闹聒聪。","东往西来皆欲顺，不知何以作天公。"]},{"t":"和尚石","f":"七言绝句","c":["知他薙发是何年，褪下偏衫悄不言。","莫是障魔心未了，故来临水坐枯禅。"]},{"t":"晨发","f":"五言古诗","c":["晨发向封川，渐逼苍梧境。","红日露幽嶂，轻烟抹远岭。","悠悠拖鸭绿，闪闪摇金影。","崖高树转古，水曲山逾静。","何处寻桃源，我心属箕颍。"]},{"t":"工书","f":"七言绝句","c":["书逼钟王役莫逃，工书尽日是贪劳。","不如任拙都无事，坐入更深看月高。"]},{"t":"奉别都宪诚庵朱先生","f":"七言律诗","c":["丘狐穴鼠易惊猜，镇靖唯须老将材。","威压百蛮谁敢乱，江清千里我能来。","含生得露枝枝别，幽谷凭春日日催。","痴病自惭非骏骨，可堪留处在燕台。"]},{"t":"二月二日总督府园亭宴赏奉谢朱诚庵都宪","f":"七言律诗","c":["二月还逢二日临，一樽容我坐花阴。","且看蓓蕾精神满，自是乾坤雨露深。","斟酌春光归酒盏，访寻物色更山岑。","从今颇识明公泽，听得儿孙几操琴。"]},{"t":"回仙亭和洞宾","f":"七言律诗","c":["颓然万物与同流，不薄人间万户侯。","懒向乾坤开话柄，直从图马看根由。","杯衔南粤千峰月，钓拂东溟万顷秋。","何处相思不相见，春风吹绿上枝头。"]},{"t":"再叠总督府园亭宴赏韵答翁佥宪","f":"七言律诗","c":["白日中天自照临，出门何敢议晴阴。","半生泉石耽成癖，一笑烟云契亦深。","南海促归游子舫，苍梧望断碧山岑。","钟期一去谁无耳，自是书生懒抱琴。"]},{"t":"禄步舟中","f":"七言律诗","c":["苍梧留赏半旬间，何事东风未许还。","茗饮颇谙冰井水，酒杯仍对顶湖山。","烟波一棹来何远，猿鸟千崖过日间。","闻道七星岩不恶，山灵应讶脚头悭。"]},{"t":"出羚羊峡","f":"七言律诗","c":["几树崖花放渐新，羚羊峡里酒呼频。","知他两面青山眼，看尽浮生几世人。","称意景偏相遇少，打头风亦不须嗔。","停舟欲问村南叟，怕有岩耕郑子真。"]},{"t":"峡口","f":"七言律诗","c":["沿堤处处露榕根，潦去江深见水痕。","远嶂排空明落日，长牵拖绿入黄昏。","天机在处看来妙，图马前头不受言。","收拾春光且归去，豆麻还绕榄山门。"]},{"t":"望古耶","f":"七言绝句","c":["渔艇轻轻泛港汊，诸山到海若排衙。","低迷远树苍烟外，老眼今朝又古耶。"]},{"t":"石门","f":"五言古诗","c":["石门何时开，巧抱两山嘴。","腾腾斗远蛇，簇簇饮封豕。","潮流自吞吐，寒石敦齿齿。","春风扇阳和，物色堪顾指。","深绛垂木棉，轻雪点郁李。","童松递远绿，细露绕香芷。","游子正西归，夕阳来照水。","濯缨歇馀韵，白云看四起。"]},{"t":"贡三角牛 其一","f":"七言绝句","c":["十牛一马两相安，食力还思稼穑难。","祇应只角生来异，也得君王一笑看。"]},{"t":"贡三角牛 其二","f":"七言绝句","c":["黄帕蒙身别故山，官舟呈进路间关。","潮田膏雨肥青草，三角何如两角閒。"]},{"t":"过蛋家租","f":"七言绝句","c":["蓢树交加翳野塘，桃花红间菜花黄。","扁舟不觉穿林杪，飞逐凫鸥过一双。"]},{"t":"夜入古镇峡与时嘉叶璧小酌","f":"七言绝句","c":["千里归来七日程，相看不厌一灯明。","残樽更出行边酒，共听蓬头雨打声。"]},{"t":"宿古镇峡","f":"七言绝句","c":["苍凉云月递微明，寂静中流歇橹声。","谁炒龙潭潭上水，聒人村犬吠残更。"]},{"t":"蚬涌舟中","f":"七言律诗","c":["水田千顷稻初登，舴艋频过气似增。","村坞烟消红日上，野塘秋入碧波澄。","闲搔短发看流水，笑傍青蒲弄紫菱。","老脚如今厌游走，祇堪来挂海门罾。"]},{"t":"扶胥感兴","f":"七言律诗","c":["了了空斋据海涯，结趺曾记坐忘时。","不辞铜鼓声惊梦，且看波罗子上枝。","大艑高舸新望眼，疏松白月旧题诗。","百年三万六千日，孟浪红尘几脱羁。"]},{"t":"题张诩母挽","f":"七言律诗","c":["西风容易卷重帏，堂北萱花不耐吹。","何处罗襦埋壮母，至今霜露泣孤儿。","光华到老人咸愿，水菽承颜我合悲。","幽思临风一挥洒，溪流南去绿漪漪。"]},{"t":"赠别石斋先生二首 其一","f":"七言律诗","c":["江门杨柳绿丝丝，折赠先生更不疑。","未可轻看惟出处，最难为别是相知。","细鳞安敢辞盆水，老凤从来识圣时。","再拜当筵无别祝，高堂垂老念归期。"]},{"t":"赠别石斋先生二首 其二","f":"七言律诗","c":["日日江门弄钓丝，清閒到老亦何辞。","风波薄暮看投楫，裘葛无心祇顺时。","身世频频催白日，文星恰恰照南陲。","一樽相送情难尽，手擘轻红饯荔枝。"]},{"t":"赠石斋先生十首 其一","f":"五言律诗","c":["惜别吾何语，秋声动海涯。","他时赋丹荔，今日赠黄花。","别足移磐石，苍波照暮槎。","大臣能体国，飞檄落烟霞。"]},{"t":"赠石斋先生十首 其二","f":"五言律诗","c":["流年过半百，敛迹只蒿逢。","秋气清炎海，苍波起卧龙。","南川留一榻，北极着双瞳。","八表虽云远，能消几日风。"]},{"t":"赠石斋先生十首 其三","f":"五言律诗","c":["三年留絮酒，不到一峰坟。","老泪空缘梦，遗碑未有文。","堪封疑此墓，谁为达明君。","今日先生往，能无感激人。"]},{"t":"赠石斋先生十首 其四","f":"五言律诗","c":["方舟展清眺，辍棹引离觞。","潮水纡寒玉，秋山带夕阳。","鹏飞天亦窄，鸥懒海俱忘。","尽把行藏意，添诗入锦囊。"]},{"t":"赠石斋先生十首 其五","f":"五言律诗","c":["好月期来夜，黄花更几朝。","远山娇入画，低岸忽吞潮。","割袂头堪白，贪诗酒易消。","倏然能化羽，霄汉逐王乔。"]},{"t":"赠石斋先生十首 其六","f":"五言律诗","c":["村酒还堪醉，官舟发未忙。","霜催乌桕赤，山引白云长。","怅望东湖水，应登孺子堂。","如何东汉士，此老善埋光。"]},{"t":"赠石斋先生十首 其七","f":"五言律诗","c":["每每定山子，诗传到海傍。","闲情今转别，老笔更无双。","黑发从渠白，流光去自忙。","寄声泉石下，痴病只寻常。"]},{"t":"赠石斋先生十首 其八","f":"五言律诗","c":["扁舟远相送，儗过峡山前。","岚气清人骨，僧居出洞天。","泥途甘我老，樽俎会何年。","不洒童儿泪，支离只赠言。"]},{"t":"赠石斋先生十首 其九","f":"五言律诗","c":["南海千年话，青天一道巾。","离言贪月白，秋思入江深。","赤手看经济，明时愧陆沈。","白云闲宇宙，去住本无心。"]},{"t":"赠石斋先生十首 其十","f":"五言律诗","c":["烟霞非痼癖，造物惜声名。","当道烦连疏，先生着不行。","秋青南海水，月满五仙城。","去去逢明主，应谙子母情。"]},{"t":"饯石斋于石门用前贪泉韵兼简诸友","f":"七言律诗","c":["鬅鬙双鬓我何言，机会能逢几百年。","共趁风光来野艇，更留声迹到名泉。","烟波在处还诸子，鸾凤看飞上九天。","回首东山明月上，更须留醉白沙船。"]},{"t":"安挥使惠靴兼诗见赠因韵奉谢","f":"七言绝句","c":["谁念柴桑赤脚人，江门情绪盎如春。","山村有酒虽堪典，争得烟霞步步新。"]},{"t":"初晴","f":"七言绝句","c":["冬雨初晴日向曛，寒螀偏傍竹间闻。","寻常又秉山中笔，只把文章换白云。"]},{"t":"重九后一日赋是日即馀余日","f":"七言律诗","c":["天生两脚踏烟霞，老态从来日日加。","不把西风移皂帽，还浇秋酒对黄花。","凉侵院竹知秋老，醉舞莱衣到日斜。","四十四年贫是福，眼边儿女莫咨嗟。"]},{"t":"拟移居二首 其一","f":"七言律诗","c":["西风吹梦别庭帏，握手凭谁话细微。","己悟山林终小隐，只从鱼鸟看真机。","栽花莳药时将晚，饭稻羹鱼愿未违。","何处洞天真可卜，即携妻子傍仙扉。"]},{"t":"拟移居二首 其二","f":"七言律诗","c":["苍苍何处绿成闱，许我移居入翠微。","白月清风贫士宅，行云流水哲人机。","付身大冶从陶铸，置足迷途易拂违。","安得此生闲到老，南川扉近白沙扉。"]},{"t":"食鱼鲫","f":"七言绝句","c":["银鲫持来向野田，童儿欢扇晚厨烟。","挥瓶小灌松花酿，共献先生一箸鲜。"]},{"t":"题丁明府三江渔樵人卷","f":"七言律诗","c":["渔樵亦爱三江老，欲制荷衣苦未成。","一笑横琴来粤海，几回飞梦绕金精。","云归谷口真成懒，月到潭心本自明。","一曲沧浪空乱耳，南溟千顷对长缨。"]},{"t":"忧旱","f":"七言绝句","c":["苗稼相将稿在田，嗷嗷万户正潸然。","乾雷滚荡无巴鼻，争讶神龙懒上天。"]},{"t":"阅都台檄催赴省试四首 其一","f":"七言律诗","c":["烟霞欲遂此生谋，台檄飞催未肯休。","总把流光销卦画，更提双眼到伊周。","行藏祇益山灵笑，贫病能忘老母忧。","谁为当权声一语，且容樗栎长林丘。"]},{"t":"阅都台檄催赴省试四首 其二","f":"七言律诗","c":["一从幽谷弄云烟，科业隳来十五年。","病骨自知难进取，衰龄谁更为周全。","芋苗催老黄梅雨，豇豆披罗小洞天。","剩水残山人不占，且随童冠看鱼鸢。"]},{"t":"阅都台檄催赴省试四首 其三","f":"七言律诗","c":["官衙严切不官书，不置山林一散樗。","儗赭青袍寻钓艇，那驱老脚又方舆。","卑微易拾圯桥履，艰阻难移节孝车。","天北天南他夜梦，相看子母欲何如。"]},{"t":"阅都台檄催赴省试四首 其四","f":"七言律诗","c":["行藏空使我怀疑，即鹿无虞事可知。","千载风云看际会，一时机轴转何谁。","苔封僻径人踪远，风荡游丝日影迟。","间点一双观物眼，还将消息认庖羲。"]},{"t":"余不阅程试义十五年今始一阅","f":"七言律诗","c":["才拈一卷一留神，睡思浓来辄欠伸。","汶上投闲应自得，昌黎惭忸可无因。","不辞筋力聊供世，祇恐轻肥解误人。","一扇葵风清到骨，北窗谁炒葛天民。"]},{"t":"将往苍梧三首 其一","f":"七言绝句","c":["利前害后两相咻，世计催人可自由。","倚棹长江看暑月，野夫乘兴欲西游。"]},{"t":"将往苍梧三首 其二","f":"七言绝句","c":["寻舟欲出更逡巡，香菌初生暑畏人。","不识顶湖山下露，风花还有去年春。"]},{"t":"将往苍梧三首 其三","f":"七言绝句","c":["自是先生懒出门，岂因残暑废杯樽。","海山六月还堪赏，红日升时露未乾。"]},{"t":"石门","f":"七言绝句","c":["火云童树共参差，江水江鸥我不疑。","团扇小挥珠汗落，相看只诵去年诗。"]},{"t":"喜侄生舟中书寄克明弟","f":"七言律诗","c":["苍凉红日欲东生，屋角西头月尚明。","伏枕忽闻添阿买，应门端足慰徐卿。","严亲地下偏含笑，小弟江东合寄声。","欲识天南今日兴，一樽携过五仙城。"]},{"t":"三江","f":"五言律诗","c":["人烟生两岸，江潦夺浮沙。","矮屋编泥竹，虚檐覆水瓜。","波回渔艇疾，风引寨旗斜。","蚬子迎船市，村醪莫肯赊。"]},{"t":"宿三水","f":"五言律诗","c":["长风何处起，雨脚散重阴。","山月能留照，江流只自深。","清宵无酷暑，远鹤有馀音。","未有悲秋意，何如蟋蟀吟。"]},{"t":"舟中","f":"七言律诗","c":["边江不省是何村，老树交加绿绕门。","万点山尖偏入画，老夫篷底正开樽。","摇风欲借芭蕉扇，坐我思寻若竹根。","更买江鱼消晚醉，鸾刀飞鲙水晶盆。"]},{"t":"再入羚羊峡","f":"七言绝句","c":["何处軥辀隔岸闻，森森榕树傍江唇。","笑看今日羚羊峡，应识当年入峡人。"]},{"t":"长利和子翼","f":"七言律诗","c":["云傍青山影傍溪，落花深处伯劳飞。","静团云日边江树，斜掩风烟面水扉。","爱踏莎堤移晚履，欲裁蕉叶当闲衣。","婆娑竹径行还住，时听軥辀对落晖。"]},{"t":"羚头峡与子翼小酌","f":"七言律诗","c":["罗列波光数百峰，一樽何惜与君同。","江流恰共诗情远，山色何如酒兴浓。","习习和风吹短鬓，萧萧凉雨洒孤蓬。","寻常一笑非人世，疑是星河有路通。"]},{"t":"宿肇庆","f":"七言律诗","c":["晚雨何须不系舟，橹声咿哑尚中流。","阴云未放端溪月，岚气先催肇庆秋。","也许炉烟飘卧榻，不教灯影照眠鸥。","鼻雷我惯甘云水，莫遣疏更到枕头。"]},{"t":"小湘峡","f":"五言律诗","c":["江水来何急，江鸥泛自闲。","濛濛天际雨，冉冉峡前山。","谷树含秋意，岚风洒醉颜。","何能伴渔子，一枕卧江湾。"]},{"t":"挂帆","f":"七言绝句","c":["洪流滚滚日趋东，西上孤舟怯柁公。","萧飒忽回山谷气，蒲帆高挂小湘风。"]},{"t":"大湘峡晚酌","f":"五言绝句","c":["帖帖江如镜，迟迟舟渐移。","都将山饯酒，不管雨催诗。"]},{"t":"夜坐和子翼","f":"七言绝句","c":["萤灯几点乱渔灯，远鼓时闻变寨更。","欲把长江来酒盏，与君聊泻百年情。"]},{"t":"漫兴","f":"七言绝句","c":["云去云来山自闲，白云何事更遮山。","天生只眼闲无用，只把云山仔细看。"]},{"t":"再游三洲岩五首 其一","f":"五言绝句","c":["蒙茸鹧鸪啼，珠露滴秋晓。","揽衣寄幽情，岩风吹料峭。"]},{"t":"再游三洲岩五首 其二","f":"五言绝句","c":["迟迟晓履移，欲去犹返顾。","了了知心人，一笑隔烟雾。"]},{"t":"再游三洲岩五首 其三","f":"五言绝句","c":["凉生昨宵雨，缺月晓仍挂。","不逢葛稚川，尽我今朝话。"]},{"t":"再游三洲岩五首 其四","f":"五言绝句","c":["晓露爱沾裳，夜游还秉烛。","飘然遗世情，高飞逐黄鹄。"]},{"t":"再游三洲岩五首 其五","f":"五言绝句","c":["青青岩畔草，点点珠露缀。","来是去年人，岩风急吹袂。"]},{"t":"舟中昼枕二首 其一","f":"七言绝句","c":["云满青山水满江，云自能闲水自忙。","一枕篷窗供打睡，任教云水两相忘。"]},{"t":"舟中昼枕二首 其二","f":"七言绝句","c":["白雨跳珠正满江，初秋一枕得新凉。","不知峡内西来水，尽日东流有底忙。"]},{"t":"发德庆","f":"七言律诗","c":["千里河山不尽期，黄茅白苇满江湄。","一樽何处逢人易，三伏中流系楫迟。","渔艇来归云漠漠，午蝉初奏雨丝丝。","如僧怪石苍江畔，似迓行舟索我诗。"]},{"t":"戏题和尚石二首 其一","f":"七言绝句","c":["童头坐老碧山棱，欲逐飞仙去未能。","点铁有丹堪点石，凭谁说与水边僧。"]},{"t":"戏题和尚石二首 其二","f":"七言绝句","c":["三千公案自缠藤，谁道三乘语足凭。","依旧结趺临野水，今年人笑去年僧。"]},{"t":"洗头二首 其一","f":"七言绝句","c":["缘鬓斑斑不自由，沧浪又送一声秋。","谁云白发还堪变，欲挽长江一洗头。"]},{"t":"洗头二首 其二","f":"七言绝句","c":["篷底烟飘一线香，含情无语对秋江。","野人惯洗尘头腻，未洗尘头几点霜。"]},{"t":"奉谢陈总戎惠墰酒","f":"七言律诗","c":["村醪野酌惯江乡，未饮元戎碧玉浆。","满目旗旌催晚醉，一江云水展新凉。","荷筒半卷初秋露，竹叶偏回午夜香。","从此诗情应更远，濯缨随处起沧浪。"]},{"t":"与秉之夜话兼寄时嘉","f":"七言律诗","c":["何处登临费杖扶，平铺在眼尽夷途。","从教鹤发催人世，不信牛衣泣丈夫。","木榻可疑他夜雨，松灯还照旧时书。","乘田委吏都吾事，只把宣尼作范模。"]},{"t":"石门留别诸友兼群从弟侄","f":"七言律诗","c":["笑拚筋力出驱驰，潦倒龙钟任后时。","秋水于人还自照，江山对我不须疑。","停舟野寺还浇酒，搔首西风忽有诗。","偶折芙蓉花在手，别筵吾不作童儿。"]},{"t":"入峡","f":"七言律诗","c":["水光摇荡碧琉璃，正值斜阳倒照时。","上峡孤舟偏入画，看山两眼欲成痴。","林泉富贵终无极，尘世风波总浪驰。","四百峰峦吾自有，一杯留嚼万年芝。"]},{"t":"峡山寺","f":"七言律诗","c":["长风两袖正披披，又上飞来引一卮。","山峙水流俱自在，白云乌帽本无期。","寻常影响驰人易，四十烟霞灭迹迟。","何事尘头空搜搜，百年疑是未醒时。"]},{"t":"凌江阻雨","f":"七言律诗","c":["欲度梅关更作疑，淩江驿下雨霏霏。","不嫌津吏迟夫马，只恐涂泥染袖衣。","庾岭阴云还自蔽，浈江流潦疾如飞。","三秋馀瘴连朝洗，谁识乾坤造化机。"]},{"t":"曲江重九日","f":"七言律诗","c":["梦魂无夜不飞还，只在慈帏笑语间。","华发又添重九节，扁舟已进曲江湾。","黄茅瘴静无秋暑，苏合杯香得晚山。","更傍滩头还击棹，月明歌枕听湲潺。"]},{"t":"吕梁道中","f":"七言律诗","c":["淮酒腾腾欺量浅，肩舆忽忽入冬深。","聊将此日冲寒意，偿却平生愿仕心。","桑枣人间频数九，轮蹄风土浪披襟。","丈夫知遇非容易，懒向行边出素琴。"]},{"t":"将至临城驿","f":"七言律诗","c":["争先路径险难量，痴立踟蹰对夕阳。","身计百年空自拙，马蹄今日为谁忙。","月当残腊还留照，鬓看寒霜转易苍。","谁道临城能馆吏，中宵犹为倒馀觞。"]},{"t":"受教职","f":"七言律诗","c":["风云敛翮向长安，老恐无才称小官。","花草渐看春意满，江湖容放酒杯宽。","闲情忽忽添诗律，归梦频频傍钓竿。","何处青精还一饱，乌纱聊裹弄吾丸。"]},{"t":"受教职将之平湖","f":"七言律诗","c":["香茶白饭在东吴，笑领微官出大都。","万里心情关子母，百年风教又平湖。","黄云紫水横孤艇，菱叶蒲梢浴晚凫。","囊底有诗樽有酒，昔吾元不异今吾。"]},{"t":"留别京师诸友","f":"七言律诗","c":["何许倾心一笑逢，黄金台下未从容。","尘途渴洒三春雨，归梦频催午夜钟。","鹤发任教垂两耳，丝桐独抱向千峰。","东风莫道无巴鼻，吹得都门绿又浓。"]},{"t":"屠秋官席上再叠","f":"七言律诗","c":["饭颗山前亦偶逢，短篇那更用先容。","烛花也解含春意，樽酒何妨及暮钟。","孤艇旧回三塔寺，一筇曾柱九龙峰。","青天乌帽吴门路，云水如今兴转浓。"]},{"t":"张后府官寓与提学宪副冯佩之夜酌话别","f":"七言律诗","c":["深云不放月轮孤，辗转方斋酒一壶。","士气西江还易振，斯文赤子更须扶。","百川宗派趋彭蠡，两袖清风过小姑。","无限衷情言未了，千年公案在鹅湖。"]},{"t":"大塘书屋为蒋世钦中书","f":"七言律诗","c":["闲窗面面罩云烟，刚占人间小洞天。","梦里陶然醒水月，眼中何处不鱼鸢。","寻春晚履真堪步，拂袖青山是几年。","料理平生端的意，小车何厌百花前。"]},{"t":"莲塘书屋为娄侍御","f":"七言律诗","c":["城市尘氛亦厌无，碧云深树草堂孤。","虚檐白月真堪看，临屋青山不用呼。","午夜星辰瞻北极，深春桃李散南都。","闲窗倘有寻归思，敢献吴江一箸鲈。"]},{"t":"休隐轩","f":"七言绝句","c":["休隐何妨额小轩，深垂白发看流年。","婆娑不了闲滋味，云在青山水在渊。"]},{"t":"留别张后府兼素","f":"七言律诗","c":["土窗茅屋断知闻，十五年来谢世氛。","云水至今还恋我，江湖何处更逢君。","留连细剪方斋烛，潦倒愁看北冀云。","再拜先生无可话，一杯留嚼野夫芹。"]},{"t":"自发潞河至郭县水浅舟胶聊成短什","f":"七言律诗","c":["村醪何处许深倾，诗思瞢腾唤未醒。","天际浮云终不定，眼边疏柳为谁青。","漕渠浅浅流春绿，午枕频频聒运丁。","万顷玻瓈一轮月，几时还我弄沧溟。"]},{"t":"叶青居","f":"五言律诗","c":["卖韭见村童，推窗正倚篷。","浮沙崩细浪，乱絮舞晴空。","吏懒陶彭泽，诗催陆放翁。","客怀吾欲语，吹断酒旗风。"]},{"t":"土门晚泊","f":"五言律诗","c":["归袂飘飘举，轻帆冉冉来。","幽花封岸觜，白日照沙堆。","旷志酬千古，虚怀贮一杯。","平生双短鬓，何处洗尘埃。"]},{"t":"河西务阻风三首 其一","f":"七言律诗","c":["絮飞沙走几曾休，归棹狂南每顶头。","自信江湖容我老，不知天意欲谁留。","浮名未有毫毛盖，真乐刚寻十五秋。","风土东吴应不恶，拟携妻子作仙游。"]},{"t":"河西务阻风三首 其二","f":"七言律诗","c":["尘氛驰逐兴全休，短发从渠白满头。","密网沙边犹自设，冥鸿天际去难留。","狂云无计成时雨，归路真愁入晚秋。","风伯如今谁敢讼，神情空傍斗边游。"]},{"t":"河西务阻风三首 其三","f":"七言律诗","c":["大块尘沙滚未休，篷窗痴坐任科头。","酒杯恋我醒还醉，鸥鸟窥人去复留。","镜里行藏周卦画，枕边熏业鲁春秋。","五风十雨能如愿，傍柳寻花极胜游。"]},{"t":"登连窝","f":"七言律诗","c":["俯仰春风礼法场，白衫还作野人装。","终朝乱耳逢骄卒，尽日无诗负锦囊。","万里乡关天自远，两行官柳日偏长。","南风每每能相阻，歌枕篷窗也未忙。"]},{"t":"良店道中二首 其一","f":"七言绝句","c":["堤柳千株拥道傍，南风拜舞不胜狂。","篷窗辗转吾何语，一瓣闲烧铁面香。"]},{"t":"良店道中二首 其二","f":"七言绝句","c":["北往南来几许舟，风沙官柳日悠悠。","不知一线漕渠水，多少行人白了头。"]},{"t":"下邳","f":"七言绝句","c":["篇诗曾记咏留侯，二十年来亦浪游。","黄石老人今在否，北风吹我过邳州。"]},{"t":"忧旱","f":"五言律诗","c":["半晌飘时雨，轰雷几夕昏。","未酬苏旱意，也受一凉恩。","散步看云脚，沈吟对麦孙。","青青野莙荙，满径为谁繁。"]},{"t":"四月二十八日狂风大作","f":"五言律诗","c":["靡靡千舟废，呜呜万嗷号。","人心空自骇，风伯也须劳。","黑发从今变，黄埃逼汉高。","闲窗谁氏子，歌枕梦魂劳。"]},{"t":"将至德州短述二首 其一","f":"五言律诗","c":["身在俱为乐，途穷亦不嗔。","南风休滞我，堤柳尚迎人。","零乱波翻玉，鬅鬙鬓欲银。","乾雷无雨意，再拜祝江神。"]},{"t":"将至德州短述二首 其二","f":"五言律诗","c":["画鹢来官舫，黄牛守野童。","麦苗今渴雨，舟子莫呼风。","书役夫催急，流亡室半空。","平生忧国意，无语向山东。"]},{"t":"过固城","f":"五言律诗","c":["宿雨含千柳，微凉变一川。","官衙趋小吏，箫鼓闹鲜船。","烟雾挥盈纸，风云思满天。","呼童买南酒，不惜杖头钱。"]},{"t":"电火","f":"五言律诗","c":["电火时惊目，雷车正辗空。","敢祈连夜雨，且杀逆头风。","麰麦枯将爇，山冈老欲童。","天瓢留一滴，搔首向苍穹。"]},{"t":"赠别同官林汝惇","f":"七言律诗","c":["今古奇逢尽偶逢，临岐欲话不曾终。","残山剩水无人占，薄禄微官与子同。","会见冰壶涵夜月，且教桃李醉春风。","铁桥粗识罗浮路，真个期君着一筇。"]},{"t":"下吕梁洪二首 其一","f":"七言绝句","c":["闪闪奔流一线斜，横波沈石乱如牙。","凭谁寄语操舟子，出入艰危莫浪誇。"]},{"t":"下吕梁洪二首 其二","f":"七言绝句","c":["电走星驰亦骇人，点篙移柁捷如神。","细看水手争长技，坐我安流自在身。"]},{"t":"彭城汉高庙","f":"七言律诗","c":["石榴花发庙门扃，偶读残碑识庙名。","香火可能留汉祖，江山依旧是彭城。","百年老兴还双履，千古争棋亦几枰。","坐我槐阴新沐罢，凉风淡淡葛衣轻。"]},{"t":"舟中小酌听宁永贞别驾说武夷","f":"七言律诗","c":["耳边频送棹歌音，九曲真源我欲寻。","先哲偶谈朱仲晦，深杯时泻密林檎。","闲窗一枕天教睡，蓬岛诸峰梦亦深。","不道凡身是仙骨，拜官还有谢官心。"]},{"t":"夹沟闸写怀","f":"七言律诗","c":["金钱不博皂囊诗，杯饭何曾谢乞儿。","京酒鲜催游子醉，年华争谓鬓毛丝。","遥遥泰岳瞻应远，采采蒌蒿步更迟。","万里亲庭天一角，夕阳翘首不胜思。"]},{"t":"题寄寄亭","f":"五言律诗","c":["寄寄亭前物，来观寄寄身。","草花应自得，云水任吾真。","白月能留照，深杯别有春。","乾坤俱旅寓，何处是天根。"]},{"t":"白泮河鲙鲤小酌","f":"七言律诗","c":["万里东南客子归，南风无日不吹衣。","白洋河内霜鳞美，老瓦盆中雪鲙飞。","碧水黄沙晴可浴，大羹元酒愿休违。","坐高淮北团团月，不把浮云怨落晖。"]},{"t":"扬州郡守招饮同李侍御观杂剧","f":"七言律诗","c":["紫李黄瓜杂酒卮，南风葛袂正披披。","浮生本亦如闲戏，卖械今真骇健儿。","潦倒且拚文字饮，输赢不了古今棋。","江山兴味元无际，太守殷勤索我诗。"]},{"t":"杨子湾偶赋","f":"七言律诗","c":["杂剧喧阗谢耳边，晚风凉气正翛然。","青茭插剑森依岸，白雨跳珠正满川。","角角水鸡初叫处，腾腾杯酒未醒前。","分明一段闲滋味，写入扬州短短篇。"]},{"t":"游金山寺","f":"七言律诗","c":["黄埃不改眼中秋，此日金山又繫舟。","地拥长江吞巨海，天教绝景镇中流。","烟云苾洌尝龙井，身世依稀在蜃楼。","欲话无生真境界，钟声不动水光浮。"]},{"t":"石门写怀","f":"七言律诗","c":["晚风吹袂晚山前，久坐松根忆去年。","本为微官轻去就，祇因慈母重留连。","还思叔子趋涪日，细嚼渊明饮酒篇。","落尽残花存故实，此生自断不须天。"]},{"t":"平轩二首 其一","f":"七言绝句","c":["世路崎岖不作难，将迎未断是危艰。","闲窗暗袖持衡手，只把灵台一镜看。"]},{"t":"平轩二首 其二","f":"七言绝句","c":["高山休刬海休填，眼界平来恰自然。","君若不拘形迹看，鸢鱼随处有天渊。"]},{"t":"赠别丰城王节之明府赴京","f":"七言绝句","c":["红烛青樽不作疑，相逢相别更相期。","专城小试栽花手，曾咏江门一老诗。"]},{"t":"灵州晚泊与舍弟克明小酌","f":"七言绝句","c":["杯酒连船看水流，一轮明月照灵洲。","德云不省今谁是，却忆东坡对子由。"]},{"t":"舟次峡山","f":"七言律诗","c":["浮云不掩洞中天，入画人撑入画船。","妻具黄鹂浇酒子，儿歌白雪向山巅。","风流与可闲烧笋，自在尧夫只弄丸。","何处合教尘梦醒，万株烟树枕头边。"]},{"t":"晓发浈阳峡","f":"七言绝句","c":["科头篷底望江湾，日在东林月在山。","风物满前谁是主，钓船撑上钓丝滩。"]},{"t":"过英德","f":"七言绝句","c":["英州城子大如斗，怪石边流作牛吼。","石屏南山索品题，却笑东坡好游走。"]},{"t":"宿太平滩","f":"七言绝句","c":["濛濛黑雾四低迷，缆繫黄茅日正西。","何处思亲肠欲断，太平滩下鹧鸪啼。"]},{"t":"观音山","f":"五言律诗","c":["谁挥仙子剑，斫断过溪山。","铁壁立千仞，丹房隐半闲。","悬崖栖老鹘，滴乳蘸洄滩。","万古留奇胜，丹青写亦难。"]},{"t":"上三坂滩","f":"七言绝句","c":["舟子挐舟日叫号，北风吹面利如刀。","欲知世路难还易，三坂滩头看着篙。"]},{"t":"五婆城","f":"五言绝句","c":["五婆山下路，不见五婆游。","只有边城水，常涵一镜秋。"]},{"t":"清溪道中偶述","f":"七言律诗","c":["天地君臣义莫逃，乘田委吏圣躬劳。","江流对我何须急，山势迫人空自高。","本乏长才供盛世，宁惭败絮拥绨袍。","千周不厌囊中易，懒向西风步楚骚。"]},{"t":"弹子矶","f":"七言绝句","c":["何须赤壁对黄州，只欠东坡一夜游。","安得身轻如过鸟，随风飞上弹矶头。"]},{"t":"蒙?道中四首 其一","f":"古风","c":["十里五里寒滩，千山万山灌木。","异香处处清流，谁别曹溪一掬。"]},{"t":"蒙?道中四首 其二","f":"古风","c":["滩恶石根齿齿，山深树映婆婆。","短景寒霜十月，南船北上风多。"]},{"t":"蒙?道中四首 其三","f":"古风","c":["船头薄暮搔首，野烧不省何山。","犬吠村舂乍急，林疏贩籴人还。"]},{"t":"蒙?道中四首 其四","f":"古风","c":["渔灯乍明乍灭，灌莽无际无边。","识破曹溪水口，何疑虎榜山前。"]},{"t":"曲江怀相国","f":"七言律诗","c":["高堂鹤发正如丝，家近洪州合请时。","阅世公应知事早，栽花吾敢怨春迟。","开元小试经纶手，韶石堪镌相国碑。","留得榄山香一片，白云何处是仙祠。"]},{"t":"返照","f":"七言律诗","c":["返照千林酒一卮，晚山刚对弄雏时。","眼中触处成真乐，身外浮名总不知。","元亮贫来还乞食，尧夫老去只游嬉。","行云流水无穷意，老树精应不作疑。"]},{"t":"课儿","f":"七言律诗","c":["摇落溪山欲暮时，軥辀声里雾迷迷。","手中残卷堪延我，篷底烧灯旋课儿。","自古箕裘谁不忝，浮生伎俩总如斯。","私情未敢祈天运，笑咏柴桑觅栗诗。"]},{"t":"平湖病目有感 其一","f":"七言律诗","c":["言闻莱妇念俱灰，短札凭谁寄玉台。","俯仰一身空自笑，昏花两眼几时开。","偷閒总道微官好，向老何堪百病催。","矮屋颓檐供熟睡，梦中慈母嘱归来。"]},{"t":"平湖病目有感 其二","f":"七言律诗","c":["呼儿扶病过墙隈，百种奇花我欲栽。","老鹤亦知栖此地，蛰虫能不待春雷。","回观不了天机妙，痴坐深存造化胎。","外暗只疑天送老，金鎞休傍眼中来。"]},{"t":"赠李野云","f":"七言律诗","c":["官居偏繫海东遥，云水中人欲见招。","千里君能来得得，一毡吾正坐寥寥。","磁瓶未醉平湖酒，春雨初肥枸杞苗。","却忆秋曹林待用，何时握手话良宵。"]},{"t":"题雪梅","f":"七言律诗","c":["阴云忽忽散溪头，偃仰寒梢露屈虬。","却把幽香埋腊雪，独留清梦在罗浮。","瘦筇又挂千峰月，秃笔初回两眼秋。","仙鹤不来冬夜永，道人何处倚江楼。"]},{"t":"平湖官署修补示督役者二首 其一","f":"五言律诗","c":["持铎频回首，乘桴未有缘。","痴儿愁露处，病叟愧多言。","井浅泥浑水，墙低树隐檐。","桄榔庵亦好，苏子乐南迁。"]},{"t":"平湖官署修补示督役者二首 其二","f":"五言律诗","c":["风烟聊顾指，府檄下多时。","蚊蚋攻三伏，鹪鹩借一枝。","经严工土役，法恕鲁侯僖。","著述非程子，龙门敢索基。"]},{"t":"露坐","f":"五言律诗","c":["当湖来暑月，坐我小池边。","欲酌樽无酒，闲吟思满天。","晓荷初贴水，豇豆正垂烟。","者树精应在，林梢奏一蝉。"]},{"t":"祷雨","f":"五言律诗","c":["一滴天飘水，雷车仰疾驱。","官僚虽有罪，赤子本无辜。","忍见苗将槁，翻愁海亦枯。","处高卑合听，万口正号呼。"]},{"t":"奉谢王判府惠米","f":"七言绝句","c":["寻常爱诵后山诗，却笑贫官解忍饥。","何处还逢赵郡使，亦留青眼照寒微。"]},{"t":"平湖病中思南归六首 其一","f":"五言律诗","c":["青铜闲拂试，照见白须髭。","浮世催人老，空山灭迹迟。","云林归倦翮，霜雪悴寒枝。","欲问商山路，疗饥有紫芝。"]},{"t":"平湖病中思南归六首 其二","f":"五言律诗","c":["掩卷千年不，沈吟不作疑。","几看空袖手，未了着残棋。","始复存消息，乾坤有合离。","金鎞时括眼，莫受翳瑕欺。"]},{"t":"平湖病中思南归六首 其三","f":"五言律诗","c":["冬卧愁襟薄，跏趺付一卢。","难将衰病骨，更听夜啼乌。","地暖思南海，情真有旧徒。","飘然决归策，争只为莼鲈。"]},{"t":"平湖病中思南归六首 其四","f":"五言律诗","c":["萧然茅屋下，云水自因依。","短履穿松去，前村摘豆归。","竹风恬隐几，山月静披衣。","胡事驱驰久，尘氛有是非。"]},{"t":"平湖病中思南归六首 其五","f":"五言律诗","c":["不识栽花地，花时解恼人。","空留看花眼，闲却故园春。","坡老门冬酒，林宗折角巾。","逍遥天壤内，吾亦任吾真。"]},{"t":"平湖病中思南归六首 其六","f":"五言律诗","c":["乐土思南海，归休道未穷。","木绵衣亦暖，延寿酒偏浓。","细雨扶留绿，熏风荔子红。","儿孙依老母，欢笑一堂中。"]},{"t":"和沈别驾元节 其一","f":"七言绝句","c":["采采红芳步更迟，睡酣尘榻掩荆扉。","白头空有青山债，仰见飞鸿又北归。"]},{"t":"和沈别驾元节 其二","f":"七言绝句","c":["树杪阴云看渐消，尚堪扶病到溪桥。","道人未有伤春意，却仗苍龙玉一条。"]},{"t":"赠别袁分教","f":"七言律诗","c":["病骨伶俜己莫支，送君扶病更江湄。","湖山尚瞩他时目，云树偏催此日诗。","聚笑一堂非偶事，相看两鬓各成丝。","寒梅却有藏春意，雪里休疑折赠迟。"]},{"t":"游福源寺","f":"七言律诗","c":["南寺烟霞如有待，东湖舴艋偶相催。","旋收春色归吟笔，肯信花枝负酒杯。","天气可人惟此日，风光随步遍蒿莱。","呼儿歌笑僧房月，谁遣罗浮客子来。"]},{"t":"吴缙折赠牡丹花因与觅莲栽","f":"七言绝句","c":["牡丹花好花端好，莲子纤花实更妍。","欲识舂陵培植意，花娇实美是天全。"]},{"t":"奉谢嘉兴郡守徐惕斋枉驾见顾平湖官署","f":"七言律诗","c":["门横蛛网径封苔，卧病俄惊使报来。","草芥何人堪接论，云宵巨眼谢频回。","春风淡荡环衿佩，元酒氤氲落玉杯。","无限阳和恩育意，却惭衰朽是非材。"]},{"t":"喜诸生会馔","f":"七言律诗","c":["讲罢声催六撞钟，青衿冉冉肃西东。","大烹本为贤才设，窃食堪羞我辈同。","箪食豆羹皆圣泽，饔人庖吏走春风。","权舆莫更添诗咏，一饭须酬一寸功。"]},{"t":"乙己清明日","f":"七言律诗","c":["青饨聊把伴芳樽，柳叶还将插鬓根。","佛子冈头应聚拜，银瓶岭上独销魂。","糟妻卧病空挥泪，慈母烧香定倚门。","南海思归归未得，斜风吹雨正倾盆。"]},{"t":"过平湖沈楷炼二秀才宅","f":"七言律诗","c":["乌纱白葛暮春前，何处烟霞得辋川。","清水人家看入画，罗浮客子笑当筵。","名花恰对平生眼，怪石真成小洞天。","萧管莫催山阁雨，清樽红烛愧留连。"]},{"t":"赏牡丹","f":"七言律诗","c":["淑气催人醉未涯，洛阳春色又官衙。","三千里外留双眼，四十年来见此花。","惯傍疏梅移晚履，几亲幽菊酌流霞。","东风一笑延今赏，坐看游蜂到日斜。"]},{"t":"闽使来聘","f":"七言律诗","c":["平生肉眼非衡鉴，遥枉诸侯走币书。","两浙官舟催欲发，八闽风物信何如。","曾贪白月捞潭底，更觅遗珠到海隅。","俯仰乾坤留一笑，夕阳烟树半模糊。"]},{"t":"度紫溪岭","f":"七言律诗","c":["虹光已烛海东头，草露凝珠泾未收。","翠展晴峦千卷画，凉催孤雁一声秋。","肩舆忽忽穿林杪，诗思腾腾逐涧流。","山水八闽端有债，他年空作梦中游。"]},{"t":"度分水关","f":"七言律诗","c":["玉笋参天着数峰，清秋留赏兴偏浓。","东南地脉交分处，闽粤山河控御中。","关吏逡巡开野酌，丁夫奔走认衰容。","望郎石畔无纤翳，不道斯文运适通。"]},{"t":"望郎石","f":"七言绝句","c":["望郎身寄鬼门西，郎去频年望欲迷。","心胆已无云雨梦，手中黄口尚提携。"]},{"t":"舟中初见武夷山","f":"七言律诗","c":["四十年来劳梦想，一杯今始识真容。","沿流莫遏穷源兴，老我堪寻若个峰。","仙子迹深山间寂，棹歌声断翠蒙茸。","怀贤适任搜求责，祇恐虚岩有卧龙。"]},{"t":"别武夷山","f":"七言律诗","c":["步步移舟步步迟，一回转盼一寻思。","相看此老终无语，抒写吾心却有诗。","树色苍苍含别恨，溪流送送出晴漪。","相逢不尽今朝兴，莫道天留忆武夷。"]},{"t":"过延平怀愿中先生","f":"七言律诗","c":["未燃精诚一瓣香，官舟催发向茶洋。","闽山本为名贤重，溪水何如道脉长。","城面人家临睥睨，祠前树色照秋阳。","缅怀高弟枢趋处，应有神灵护讲堂。"]},{"t":"经小箬","f":"七言绝句","c":["古榕深树碧烟凝，小箬山前望眼明。","粤客思亲原有泪，軥辀休送断肠声。"]},{"t":"到福州","f":"七言律诗","c":["危滩历尽得安流，十里肩舆向福州。","人物权衡空自愧，江山英采共谁收。","栽花只手闲偏惯，阅世双眸老未休。","箫鼓远劳诸贵迓，一樽同醉玉壶秋。"]},{"t":"闽南试院典文偶赋","f":"七言律诗","c":["微官何处尽平生，文字真愁误俊英。","眼底深沈端有分，镜中妍丑本无情。","香风淡淡飘丹桂，白月迟迟照省城。","收拾秋光浑未了，更依南斗认疏星。"]},{"t":"试院中秋赏月和章方伯","f":"七言律诗","c":["阅世空惊四十霜，年华如月到中央。","褰帘共赏人非少，袖手还容我在傍。","眼底毫芒堪遍烛，酒中斟酌岂须忙。","八闽诗料元无限，暂借银蟾一夜光。"]},{"t":"游鼓山灵源洞因宿鼓山寺六首 其一","f":"五言律诗","c":["石鼓山前兴，经旬念未酬。","片云来倏忽，空翠任迟留。","万象归杯酒，千峰豁醉眸。","不知天壤内，何处是瀛洲。"]},{"t":"游鼓山灵源洞因宿鼓山寺六首 其二","f":"五言律诗","c":["旋制茅根笔，悬崖欲大书。","老怀堪尽展，绝景更何如。","云水真无性，乾坤是客居。","僧庐新结构，高枕我来初。"]},{"t":"游鼓山灵源洞因宿鼓山寺六首 其三","f":"五言律诗","c":["开山谁是祖，拂袖我今来。","纵饮宁辞酒，欢书已破苔。","悬崖搜古迹，绝涧洗黄埃。","羽化疑今日，天风步步催。"]},{"t":"游鼓山灵源洞因宿鼓山寺六首 其四","f":"五言律诗","c":["爱此灵源洞，真成烂熳游。","名儒书未剥，仙子迹还留。","喝水僧何去，栖禅窟自幽。","白云如恋我，飞逐鼓山头。"]},{"t":"游鼓山灵源洞因宿鼓山寺六首 其五","f":"五言律诗","c":["何处不堪老，浮生空自忙。","石门开洞古，松径绕云长。","恋恋情何极，看看世欲忙。","难描今日兴，更憩老僧床。"]},{"t":"游鼓山灵源洞因宿鼓山寺六首 其六","f":"五言律诗","c":["鼓山今夜月，照见宦游情。","僧榻尘稀到，松风韵自清。","谷虚疑有守，城远不闻更。","忽忆同心侣，朝来合寄声。"]},{"t":"徐方伯刘太参沈亚参招饮平远台","f":"七言律诗","c":["团团孤石对层峦，小坐堪留半日欢。","僧径曲随虚阁转，秋山间带夕阳看。","行云流水情何远，乌帽青天眼自宽。","更饮香醪添晚醉，诸公忘己我忘官。"]},{"t":"重九日张侍御招饮元妙寺时董侍御林大行人泮及弟佥宪包进士咸在席酒酣因和张侍御旧游韵二首 其一","f":"七言绝句","c":["笋舆欲尽碧峰头，翠竹深松景自幽。","潦倒共拚今日醉，不知萸菊为谁秋。"]},{"t":"重九日张侍御招饮元妙寺时董侍御林大行人泮及弟佥宪包进士咸在席酒酣因和张侍御旧游韵二首 其二","f":"七言绝句","c":["醉来萸菊满簪头，况值僧居景最幽。","七步何才争出手，兴馀书破一山秋。"]},{"t":"沈亚参邀华林寺酌别时徐方伯刘大参索诗留别走笔奉答","f":"七言律诗","c":["闽南风物颇穷搜，更为闽南一日留。","方伯忽催言别句，越山难尽满怀秋。","轻阴且莫愁时暮，醴酒还堪话壮游。","聚散从来非偶事，出门刚念倚门忧。"]},{"t":"董侍御宿南察院","f":"五言律诗","c":["乌台清密地，木榻一宵同。","爱国心逾赤，忧时话至公。","霜威侵布被，月色透帘栊。","失记三更梦，鸡声乱晓钟。"]},{"t":"过壶公山","f":"七言绝句","c":["壶公何物钟灵秀，更为壶公一品题。","老眼何曾忘五岳，笋舆吟过木兰溪。"]},{"t":"同安谒朱晦庵先生祠","f":"七言律诗","c":["翻然徒步往忘疲，却忆先生在邑时。","他日官衔虽主簿，如今斯道却宗谁。","祠前榕叶聊供扫，炉内枫香逐旋吹。","无限斜阳凝伫意，寒蝉犹听傍深枝。"]},{"t":"龙溪李邑宰用刘大参韵见赠仍和奉寄","f":"七言律诗","c":["云霄万里看程期，海内何常乏所知。","黄甲声华君作县，丹霞聚笈我留诗。","牛刀小试经纶手，襦裤终兴恺悌思。","寄谢参藩刘伯长，海宾深望抚流离。"]},{"t":"谢龙溪李廷信明府惠肩舆","f":"七言律诗","c":["笋舆潇洒漳南路，却爱君侯样制工。","款段惯曾驮李贺，蒲轮今益愧申公。","行边风日轩窗小，醉里云山兴味浓。","共敝车裘今几见，可无诗句播闽东。"]},{"t":"过恶溪","f":"七言绝句","c":["红桥东接义安城，俯盼洪流一战兢。","何事鳄鱼驱已久，恶溪犹有恶之名。"]},{"t":"潮州谒韩文公祠二首 其一","f":"七言绝句","c":["扶留叶子裹槟榔，欲献君侯恐不尝。","仰止高山聊展拜，名香一线是心香。"]},{"t":"潮州谒韩文公祠二首 其二","f":"七言绝句","c":["香拈一线傍峰头，海色山光共劝酬。","莫道开元无眼孔，天留声迹重潮州。"]},{"t":"潮州林太守邀金山小酌","f":"七言绝句","c":["乌石参差出凤城，一樽聊此话平生。","磨崖细认模糊字，怕有昌黎刺史名。"]},{"t":"别潮州","f":"七言绝句","c":["阃侯兵卒初辞去，刺史渔丁复遣来。","传食如今非孟子，滩声愁听恶溪雷。"]},{"t":"过程乡","f":"七言绝句","c":["溪流曲曲入程乡，蓬底晨吹晚稻香。","总道渔翁无一事，持篙犹为急滩忙。"]},{"t":"过龙川","f":"七言绝句","c":["何处逢人话小苏，黄茅冈绕一城孤。","间关回首闽南路，今日扁舟得顺途。"]},{"t":"河源道中闻秉之囟问","f":"七言律诗","c":["恶声传送耳边来，尚冀流言辍我哀。","浮世百年真是梦，壮心今日已成灰。","流溪有恨同呜咽，造化无情故迫催。","满目云山总愁思，好怀从此向谁开。"]},{"t":"惠州阻风","f":"七言绝句","c":["杨风白浪使人愁，两日归舟不自由。","白鹤峰前悭一顾，却疑苏子暗相流。"]},{"t":"银瓶阡感事","f":"七言律诗","c":["银瓶岭畔剪蒿莱，谁盗坟傍土一坏。","榻外岂容人鼾睡，眼中刚遇我归来。","青山到处堪埋骨，古墓边头忍斫培。","惭愧许孜招感事，空垂血泪抚松栽。"]},{"t":"次韵张廷实兼呈白沙先生","f":"七言律诗","c":["酒盏天教酌五湖，浮沈却笑我非夫。","丝桐挂壁今成懒，天地知音敢谓无。","两鬓忽随尘梦改，一腔还照月轮孤。","题诗小放风花手，旋制茅根笔可书。"]},{"t":"次韵白沙先生赠别","f":"七言律诗","c":["诗亦韶音酒亦春，故来江阁坐江云。","鸾和耳孔开三日，海酌磁瓯醉十分。","短发催人偏易白，青山留我亦成群。","通宵柳渡溪头话，一棹烟波却谢君。"]},{"t":"寒雨","f":"七言绝句","c":["斜斜细雨北风吹，正值春分节近时。","绿草贪生偏自得，只愁红紫损花枝。"]},{"t":"浈阳峡舟中偶述寄白沙潮连诸友","f":"七言律诗","c":["溪曲山深月影孤，猿声争亦笑迷途。","一官老去愁将母，七尺贫来愧病躯。","耳畔怯逢新杜宇，镜中还是旧头颅。","江门烟水潮连酒，祇欠园田二顷馀。"]},{"t":"庄定山先生闻受平湖典教叠韵赠六律依韵奉答 其一","f":"七言律诗","c":["冥鸿天际有遗音，指畔宁须弄我琴。","流水自存深浅意，白云应识去来心。","五湖春在身堪老，一棹风多力不任。","细读医方延道侣，门前芳草履痕深。"]},{"t":"庄定山先生闻受平湖典教叠韵赠六律依韵奉答 其二","f":"七言律诗","c":["空中不省是何音，人在烟波指在琴。","月白风清能几夜，云闲水止若为心。","双凫落处兴非浅，只手拈时醉莫任。","浦子城边遗一老，万花丛里坐春深。"]},{"t":"庄定山先生闻受平湖典教叠韵赠六律依韵奉答 其三","f":"七言律诗","c":["啼鸟屋角忽传音，懒向西风拂素琴。","棋局未谙浮世里，马图空认圣人心。","一锄旷野还堪把，两脚青山病未任。","颠倒一场春梦醒，出门长笑大江深。"]},{"t":"庄定山先生闻受平湖典教叠韵赠六律依韵奉答 其四","f":"七言律诗","c":["武夷曾听棹歌音，闽越归来壁挂琴。","丹汞可无留世诀，白云长有傍山心。","平湖风月分诸子，南海烟波钓一任。","何处折腰还五斗，渊明诗句酒中深。"]},{"t":"庄定山先生闻受平湖典教叠韵赠六律依韵奉答 其五","f":"七言律诗","c":["从来至乐是无音，会意深时岂在琴。","律管候知残腊气，梅花描出老天心。","何愁病骨医无药，祇恐春杯醉不任。","痴坐白头何所有，满庭芳草雨中深。"]},{"t":"庄定山先生闻受平湖典教叠韵赠六律依韵奉答 其六","f":"七言律诗","c":["谁道东南有赏音，不闻三载定山琴。","梅花总落题诗手，春雨偏知种树心。","何处高僧来惠远，他时好语话周任。","指头江浦平湖路，却恨瓜州一水深。"]},{"t":"参军张兼素挽诗三首 其一","f":"七言律诗","c":["手翰封缄却寄君，忽传凶讣到江滨。","交情似我空扪泪，真率如君更几人。","赤手扶危陈短疏，丹心爱国是忠臣。","芳名自合留青史，岂少封章贲老亲。"]},{"t":"参军张兼素挽诗三首 其二","f":"七言律诗","c":["曾接诸贤坐几庵，方斋醇美众交谈。","三年报政涪兼宿，两府参军北又南。","故里盖棺君莫憾，他乡闻讣我何堪。","庐陵忠节诸贤庙，更置罗张亦不惭。"]},{"t":"参军张兼素挽诗三首 其三","f":"七言律诗","c":["江门遥赋忆君诗，正值君亡半月时。","昨暮云山思共酌，今朝烟雨忽成悲。","阴阳机括终难识，生死交情更不疑。","何日西屯挥老泪，为君扶起墓前碑。"]},{"t":"阻风留别江佥宪兼呈冯提学二首 其一","f":"七言绝句","c":["酒醒斜阳睡起时，瞢腾春思尚如痴。","扬风白浪摧诗急，却讶诗翁不出司。"]},{"t":"阻风留别江佥宪兼呈冯提学二首 其二","f":"七言绝句","c":["春杯一聚未从容，天意分明又北风。","庐阜鄱阳他日约，敢将诗债问冯公。"]},{"t":"松庄翁挽","f":"七言律诗","c":["病眼摩挲读墓碑，知君有子立清时。","篇诗此日还堪赋，老泪平生不浪垂。","新土一丘封寂寂，深松万个色离离。","荣华欲就孤儿养，不恨琅琊作计迟。"]},{"t":"次韵庄定山赠徐佥宪","f":"七言绝句","c":["定山金榜旧同袍，邂逅洪城识俊豪。","莫道卑官无眼孔，卑官眼孔或时高。"]},{"t":"钱佥宪母挽","f":"七言律诗","c":["教子劬劬未仕初，灯前绩纺膝前书。","宪台有禄堪供奉，泉壤无由问起居。","钱氏千秋思令母，松庄一老共幽庐。","慈乌反哺心何了，也见光荣七十馀。"]},{"t":"和顾能","f":"七言律诗","c":["一柱无缘障急流，白云回首思绸缪。","共拚酒盏销红烛，懒插花枝上黑头。","鸿鹄心情空自远，江湖烟浪尚韬忧。","凭君会我难言意，更傍青荷买钓舟。"]},{"t":"和孙良璧居士","f":"七言律诗","c":["持杯只手是天生，来向当湖弄月明。","诗债未能酬岭海，斯文何敢说权衡。","行窝遇乐家家到，好鸟催归日日鸣。","过眼尘头真易白，与君那惜话衷情。"]},{"t":"如斯亭次韵庄定山","f":"七言律诗","c":["宣父含情伫立时，难言易见却如斯。","闲观宇宙无穷意，似与鸢鱼两物知。","活泼泼中那有我，慢腾腾处欲呼谁。","鳌峰亭子来何日，笑和双泉二老诗。"]},{"t":"喜徐光岳来访平湖","f":"七言律诗","c":["几夜青灯报好花，朝来扶病理乌纱。","定山妙笔承传信，天姥黄精忽拜嘉。","违隔仙容刚十载，留连尘榻更谁家。","卑官莫道无供给，亦有东湖水荐茶。"]},{"t":"放诸生依诏侍亲八月九日郑提学宪副驳檄至","f":"七言律诗","c":["梦断丹青指不弹，疏慵关涉事无端。","宁亲造次容诸子，驳檄分明罪小官。","乌鸟私情林谷远，圣明恩意海天宽。","上弦月子中秋近，夜夜呼儿笑共看。"]},{"t":"阅诸生课","f":"七言绝句","c":["铢铢两两较高低，眼渐昏来意渐迷。","弄月吟风程伯子，不知何以学濂溪。"]},{"t":"题鹅溪书屋","f":"七言律诗","c":["曾向鹅湖着两眸，鹅溪书屋又谁修。","频年未了惟诗债，尽日堪看是活流。","庭草翠深空阁雨，梦魂凉浸碧山秋。","瘦筇莫厌溪桥僻，朝市尘氛易白头。"]},{"t":"奉别徐郡侯怀柏先生考绩之京","f":"古风","c":["老我行藏欲话难，先生麾节别吴?。","风云会处声光远，势分忘来礼数宽。","预有忠勤书最绩，尚留恩意及卑官。","支离不敢秋江饯，却把诗篇写肺肝。"]},{"t":"宿大乘寺","f":"七言律诗","c":["招提昨梦应延我，舴艋今朝却为谁。","松桧形容犹未改，梅花消息尚堪疑。","尘庵寂静偏宜睡，僧榻跏趺忽有诗。","烧罢黄龙香一线，佛前灯影照琉璃。"]},{"t":"舟张泾汇示诸生","f":"七言绝句","c":["苍田红树入霜天，独立船头思渺然。","诸子欲谙云水性，试留双眼看晴川。"]},{"t":"丁未平湖重九日","f":"七言律诗","c":["村醪何处亦堪赊，天宇初晴景最佳。","黄菊未开重九节，老夫惟对木犀花。","狂挥秃笔诗盈纸，步遍青莎月满衙。","却忆去年今日酒，滥陪骢马醉元沙。"]},{"t":"重九叠韵改犬子时表稿","f":"七言律诗","c":["重阳无酒亦须赊，此夕烟云景最佳。","篱菊乍开今日眼，木犀犹放晚秋花。","闲观宇宙逢双鬓，指点风光坐一衙。","不识江门今日酒，许谁同醉白鸥沙。"]},{"t":"景庵","f":"七言律诗","c":["名题金榜桐乡令，何处烟云寄此庵。","六一风流真可慕，端溪山水果无惭。","瘦筇短履何曾厌，怪石奇岩自错参。","识破利名关是梦，振衣归去面澄潭。"]},{"t":"赠别李邑宰","f":"七言律诗","c":["我笑思归未得归，君今先我上渔矶。","韭芽香嫩供春饼，桑枣林疏步夕晖。","拍拍千杯延杂剧，酣酣一枕饫轻肥。","三竿日上门犹闭，懒与儿曹管是非。"]},{"t":"林居鲁人京过槜李往饯不遇留此识别","f":"七言律诗","c":["春风过眼又芳菲，斗酒追寻愿适违。","优诏迁官君合处，衰年多病我须归。","新蒲细柳皆诗料，淡雾浓云信笔挥。","白首相期还洗耳，何曾卧病泣牛衣。"]},{"t":"题周文郁暴日台","f":"七言律诗","c":["剪棘诛茅次第修，百年身计此中收。","见成好饭能供子，入望高人正倚楼。","炙背三冬仍傍母，蒙头一枕胜封侯。","莫嫌幽僻东涌地，且看南溟昼夜流。"]},{"t":"侍御袁德纯挽三首 其一","f":"七言律诗","c":["昨暮长风送客悲，满庭飞霰杂忧疑。","谁催侍御归长夜，欲叫苍天一问之。","垂老真诚君未改，到头青白我能知。","豺狼未殄身先殒，应有高人解勒碑。"]},{"t":"侍御袁德纯挽三首 其二","f":"七言律诗","c":["徒传岭海净妖氛，搔首西风哭暮云。","二十年来心共照，三千里外讣初闻。","君明大义曾期我，我有狂言亦嘱君。","掩抑乌台他日意，几时和泪滴孤坟。"]},{"t":"侍御袁德纯挽三首 其三","f":"七言律诗","c":["西屯幽壤可曾扃，又报龙川坠德星。","浮世尘头偏易白，皇天老眼为谁青。","愁生瘴海风声改，梦断乌台雨泪零。","不独岭南公论在，太平人口是碑铭。"]},{"t":"闻有上荐剡者","f":"五言律诗","c":["微官成懒散，荐剡孰开陈。","亨泰逢清世，支离笑病身。","双眸回宇宙，千载几君臣。","舒卷床头易，空庭草自春。"]},{"t":"读冬曹林居鲁荐疏有感","f":"五言律诗","c":["贫贪微禄养，辗转未能归。","经史频留眼，行藏愧炳几。","春回花自笑，天远鹤孤飞。","读罢虞衡疏，林风荡葛衣。"]},{"t":"挽林从信佥宪","f":"七言律诗","c":["八壶山下信多贤，何处泷冈觅旧阡。","夜月啼乌仙有疏，春风南国士无缘。","难将拙笔描真像，欲置生刍到墓前。","莫问百年修短事，凤毛霄汉正翩翩。"]},{"t":"福源寺偶赋","f":"七言律诗","c":["不嫌荒寂南禅寺，斜日肩舆偶独来。","古树迎人僧径僻，秋光如水稻花开。","寻常薄酒留真偈，三两青衿恰侍陪。","识破华严无一字，更容何物入灵台。"]},{"t":"题包翁双庆卷","f":"七言律诗","c":["人间称意事难逢，六十年来却受封。","甲子又添新日月，乌纱聊饰旧形容。","间寻二仲开醇酎，笑引诸孙弄瘦筇。","李径桃溪春似海，更留青眼看长松。"]},{"t":"郡守沈元节招饮当湖和沈刚夫秀才","f":"七言律诗","c":["笑把当湖作故乡，话投诸阮总贤良。","氤氲春色催人醉，夹杂汀花入酒香。","几许扁舟来我辈，满前生意为谁芳。","湖南一点星浮水，安得层楼揖太阳。"]},{"t":"德藏寺和嘉兴徐郡守题壁 其一","f":"七言律诗","c":["佛子阶除处处幽，一凉如水入深秋。","林花欲放堪浇酒，身事无端更倚楼。","青草蒙茸随雨化，白云缥缈自天游。","蒲团试问安禅老，可识人间半点愁。"]},{"t":"德藏寺和嘉兴徐郡守题壁 其二","f":"七言律诗","c":["法镜留将法眼观，松风细细动波澜。","僧床佛阁聊供睡，龙马图书掩不看。","杯饭寻常忘我老，匣琴容易向谁弹。","知心却有东篱菊，不择先生是小官。"]},{"t":"中秋当湖文庙赏月","f":"五言律诗","c":["平分秋一半，步入圣宫墙。","心照中天月，杯衔碧玉浆。","木犀熏湛露，蟾阙晕祥光。","羽化疑今夕，飘然上彼苍。"]},{"t":"寿湖隐方翁","f":"五言律诗","c":["科头向南亩，七十四回春。","不信乌纱帽，能荣白发人。","稻苗看正熟，村酒酿来醇。","又见诸孙子，幽居各买邻。"]},{"t":"戏题当湖山月池","f":"五言律诗","c":["他时谁捧土，蕞尔便名山。","陈迹浮烟没，先生一笑看。","雨馀蛙吹满，秋霁鹤忘还。","却有当湖月，频过水石间。"]},{"t":"游德藏寺四首 其一","f":"五言律诗","c":["频年来德藏，莫发老夫诗。","秋兴乘今日，禅林索旧碑。","荒池空偃月，杂树屈虬枝。","欲话无生事，圆机却是谁。"]},{"t":"游德藏寺四首 其二","f":"五言律诗","c":["好景多魔在，僧贫寺半荒。","径深蒿艾密，墙矮薜萝长。","僻地成痴坐，秋林正夕阳。","难穷清气味，一瓣广南香。"]},{"t":"游德藏寺四首 其三","f":"五言律诗","c":["缓缓纡吟步，青莎叠砌间。","官无文案累，身似老僧间。","蝉奏冬青树，云藏薜荔关。","心源端解了，何处觅深山。"]},{"t":"游德藏寺四首 其四","f":"五言律诗","c":["大隐留斯地，喧中寂本佳。","雨肥苍耳色，秋老决明芽。","佛了三生幻，僧防一念差。","经函千万卷，苦海浩无涯。"]},{"t":"泛当湖八首 其一","f":"五言绝句","c":["青青湖畔草，泛泛波中鸟。","杯酒入烟云，断隔秋天杳。"]},{"t":"泛当湖八首 其二","f":"五言绝句","c":["闲持一杯酒，移艇傍疏竹。","白鸟忽飞来，湖田雨初足。"]},{"t":"泛当湖八首 其三","f":"五言绝句","c":["数声采莲歌，秋波杳如海。","不遇种莲人，安得莲堪采。"]},{"t":"泛当湖八首 其四","f":"五言绝句","c":["湖水荡渔舟，渔舟戏湖水。","烟波日相寻，何时清见底。"]},{"t":"泛当湖八首 其五","f":"五言绝句","c":["白雨乱跌珠，汀云散还聚。","凫鹥出菰蒲，迎船飞故故。"]},{"t":"泛当湖八首 其六","f":"五言绝句","c":["迟迟游子舟，点点波心雨。","沿流入回溪，坐当秋竹舞。"]},{"t":"泛当湖八首 其七","f":"五言绝句","c":["烟火几渔家，边湖夹疏树。","扁舟三五人，坐入秋天暮。"]},{"t":"泛当湖八首 其八","f":"五言绝句","c":["细雨洒深竹，轻烟罩孤屿。","倏然坐迟暮，欲语不能语。"]},{"t":"自庆五十和顾能见赠五首 其一","f":"五言律诗","c":["百年今已半，天与一官闲。","名忝师生分，恩同骨肉间。","黄花亲寿斝，歌鸟祝南山。","老负斯文托，如今更厚颜。"]},{"t":"自庆五十和顾能见赠五首 其二","f":"五言律诗","c":["百年今已半，宏治适时雍。","岂厌儒官小，均陶大化中。","乾坤春未老，鱼鸟思何穷。","圆转天机活，吾今亦尚同。"]},{"t":"自庆五十和顾能见赠五首 其三","f":"五言律诗","c":["百年今已半，天意苦栽培。","地僻人过少，春深花自开。","光韬云里月，香淡雪中梅。","此意神仙会，王乔鹤不来。"]},{"t":"自庆五十和顾能见赠五首 其四","f":"五言律诗","c":["百年今已半，身外总浮云。","开径延三益，飞觞醉十分。","皇天回斗柄，南极照斯文。","无限难言意，逢君欲告君。"]},{"t":"自庆五十和顾能见赠五首 其五","f":"五言律诗","c":["百年今已半，更作万年期。","且了男儿事，宁求举世知。","秋林初返照，篱菊正开时。","满引杯中酒，还吟自庆诗。"]},{"t":"偶述三首 其一","f":"七言绝句","c":["木犀香亚几枝低，尽日花边坐欲迷。","何处棹歌声转急，缓寻幽草更前溪。"]},{"t":"偶述三首 其二","f":"七言绝句","c":["乘田委吏不辞低，五百年来几醒迷。","一脉还寻洙泗水，异香流处是曹溪。"]},{"t":"偶述三首 其三","f":"七言绝句","c":["坐入深更月向低，天灵一点照群迷。","何人不奈秋光好，时送歌声过北溪。"]},{"t":"题两浙旬宣卷","f":"七言律诗","c":["天心仁爱圣明朝，阴沴频年未尽消。","眼底名藩参浙水，马前春意遍童谣。","潜鳞涸辙需甘泽，赤子穷檐望使轺。","何处覆盆光未照，紫薇花下更逍遥。"]},{"t":"除夕自勉","f":"五言古诗","c":["我来当湖滨，坐阅五除夕。","年光倏流电，半百过瞬息。","俛仰畴昔时，抚景恒自惜。","遑遑若追忘，万里摇鞭策。","圣途虽云远，壮心如铁石。","仰钻日复日，寸累仍铢积。","晨飧未及饱，夕寝宁安席。","云胡远今时，自恕还自适。","颓颜无复少，短发日向白。","天衢浩无涯，进寸殊退尺。","古来圣贤人，未免遭穷厄。","顾肯当尘途，掷此千片璧。","念我意中人，耿耿明寸赤。","持此一杯酒，自讼还自责。","丈夫志千古，讵忍为形役。","百年能几时，逆旅栖过客。","煌煌照红烛，感此岁除迫。","杳然兴遐思，四顾樊笼窄。","晴露有佳花，狂风无健翮。","俭德勤自修，舒卷床头易。","乾坤重担子，知上谁肩脊。"]},{"t":"奉寄彭从吾亚卿乞致仕养亲","f":"七言律诗","c":["曾持寸赤达公文，允领微官本为贫。","七十年馀慈侍下，三千里外梦归频。","遗羹直欲尝君食，刻木何如事活身。","九万谁云天听远，海滨今日遇名臣。"]},{"t":"铁佛寺次夏大卿见赠韵","f":"五言律诗","c":["来过铁佛寺，风雨半旬馀。","僧阁鸣琴籁，蜗牛走篆书。","云霞双眼在，天地一舟虚。","未尽他年语，还寻长者庐。"]},{"t":"寓铁佛寺时奉藩檄总修两浙实录","f":"七言律诗","c":["佛子轩窗隔翠微，微官何地更相宜。","梅花月照杯传处，坞竹烟深履步时。","闲里风光描不尽，静中鱼鸟看成痴。","凡才未悟春秋旨，却与名藩管是非。"]},{"t":"承彭亚卿从吾顾纂修局","f":"七言律诗","c":["节声恬不到云隈，松径肩舆忽一来。","尽日喜闻经济话，如今真识栋梁材。","僧厨也解供蔬食，属吏何妨捧酒杯。","燕语莺啼春似海，百花犹待几时开。"]},{"t":"承陈谢二侍御顾纂修局","f":"七言律诗","c":["松桧森罗一径斜，绣衣联辔入烟霞。","尽教春意回枯槁，未遣秋霜着早花。","喜傍云山开眼孔，细烹泉乳泛茶芽。","僧轩半晌非容易，无限风光被物华。"]},{"t":"次韵张太守述怀见寄三首 其一","f":"五言律诗","c":["史馆依僧寺，三春谢市嚣。","翻然来好句，端足慰无聊。","济世君心赤，贪山我兴饶。","崇卑各有分，期不负当朝。"]},{"t":"次韵张太守述怀见寄三首 其二","f":"五言律诗","c":["万虑日忉忉，偏能变二毛。","闲官聊自适，大冶任甄陶。","千里寄非小，诸侯位本高。","云龙终有会，应不续离骚。"]},{"t":"次韵张太守述怀见寄三首 其三","f":"五言律诗","c":["小荷擎雨盖，正是夏初时。","日日看云脚，行行傍野池。","花前聊引酌，兴在辄题诗。","无限悠然意，升沈问不知。"]},{"t":"竹间偶赋","f":"七言绝句","c":["春去禅林绿已肥，竹间杯酒亦相宜。","漆园本是逃名吏，懒向琅玕刻小诗。"]},{"t":"铁佛寺偶成","f":"古风","c":["三径五径疏竹，千株万株乔松。","游子贪看铁佛，忘却南北高峰。"]},{"t":"游南屏偶题雨庵卷","f":"五言绝句","c":["君庵偏爱雨，我却喜晴来。","晴雨休相泥，朱颜一笑开。"]},{"t":"送吴方伯入京","f":"七言律诗","c":["宿雨尘途洗更清，恰逢方伯入神京。","千年共祝今明圣，四海欢呼颂太平。","流水有情催画鹢，青山无数导霓旌。","微官久在春风里，不用临期叙别情。"]},{"t":"游西湖二首 其一","f":"七言律诗","c":["眼傍西湖忽有诗，湖山应讶我来迟。","十年倏尔成何事，一笑茫然似故知。","细柳新莺迎画舫，丹楼碧阁漾清漪。","凭谁为秉王维笔，貌出闲官酩酊时。"]},{"t":"游西湖二首 其二","f":"七言律诗","c":["千首西湖合与诗，东风花信任迟迟。","陶然云水三春意，似有凫鸥几个知。","镜面湖光含曙色，佛头山子醮清漪。","何能卜筑孤山下，一日频游十二时。"]},{"t":"重游虎跑寺二首 其一","f":"七言律诗","c":["尘鞅无缘脱俗羁，肩舆一笑任行迟。","绿肥晴日浮光晕，凉淡晨烟罩碧漪。","泉韵又添今日兴，松阴犹记昔年诗。","繁花过眼开还落，只有青山似旧时。"]},{"t":"重游虎跑寺二首 其二","f":"七言律诗","c":["骏骨从来不受羁，蹉跎真愧烛几迟。","松风尚忆吹残梦，泉影还看弄碧漪。","涧鸟静听游子语，林僧争乞老夫诗。","摩挲松径寻碑迹，却忆东坡抚掌时。"]},{"t":"涵碧亭为陈侍御","f":"七言律诗","c":["边池亭子构来新，水色山光入梦频。","伯氏闲情呼仲氏，后人高致绍前人。","春随鱼鸟看何厌，景幕烟霞写未真。","惟问三山贤柱史，几时凭槛看丝纶。"]},{"t":"楚使来聘二首 其一","f":"七言律诗","c":["斯文衡鉴愧多贤，云水天催未了缘。","衡岳风光劳梦想，洞庭秋色可谁专。","直期心醉千山景，不用诗留万口传。","何处明珠偏照乘，试留吾网白重渊。"]},{"t":"楚使来聘二首 其二","f":"七言律诗","c":["三千里外币书来，老眼湖南又一开。","游走自知山有债，搜求谁道世无才。","微官薄禄终何补，大地名花本欲栽。","半幅秋帆乘远兴，洞庭江汉梦相催。"]},{"t":"宿严州天宁寺 其一","f":"七言律诗","c":["官閒我亦何拘碍，又向天宁一借眠。","风雨净除三伏暑，梦魂凉浸万山烟。","窗临木杪宜仙枕，地隔溪流断俗缘。","寄语频游严少府，几人参破野狐禅。"]},{"t":"宿严州天宁寺 其二","f":"七言律诗","c":["浮生半日閒难得，已借僧床十日眠。","建茗几烹严子濑，牙香初散富春烟。","诸侯传食端堪愧，山水嬉游是夙缘。","杯酒未将疑老衲，醉中元亦有真禅。"]},{"t":"子陵 其一","f":"七言律诗","c":["羊裘大泽器深藏，云物终难掩瑞光。","今古几人空愧畏，乾坤此老尚轩昂。","安刘祚汉心情远，剩水残山姓字香。","描出白云舒卷意，谁家诗笔妙追唐。"]},{"t":"子陵 其二","f":"七言律诗","c":["同袍礼教未须疑，回首青山是故知。","迢递几来尘里眼，摩挲还读庙前碑。","长竿自作江湖主，寸舌谁为帝者师。","莫问荣华风烛事，棹歌留咏子陵诗。"]},{"t":"子陵 其三","f":"七言律诗","c":["桐江老子持竿手，旋转乾坤一气还。","欲识江湖关系处，试看星宿荡摩间。","难同刘汉论心曲，合与夷齐议辈班。","仰止高山千载下，身间元亦是心间。"]},{"t":"子陵 其四","f":"七言律诗","c":["羊裘坐老葛天民，物色何心到海滨。","乡曲心情须长幼，玺书名分是君臣。","千年公案留诗咏，七里滩头舣棹频。","无限青山溪一带，水云何处尽天真。"]},{"t":"次韵石斋先生赠姜仁夫进士三首 其一","f":"七言绝句","c":["茅笔新题卷一通，又留双眼浙之东。","湘湖秋色休催我，且缓蒲帆半日风。"]},{"t":"次韵石斋先生赠姜仁夫进士三首 其二","f":"七言绝句","c":["暑雨初晴濲水浮，相看握手话中流。","陶然一醉江门景，却羡仁夫解远游。"]},{"t":"次韵石斋先生赠姜仁夫进士三首 其三","f":"七言绝句","c":["严子名存旧钓台，宦途看去复看来。","乘田委吏风尘里，无分山中久闭斋。"]},{"t":"七夕过怀玉水南寺遇丁玉夫索诗走笔奉答","f":"七言绝句","c":["七夕无缘一尽欢，水南秋月爱谁看。","眼中岂少欧阳子，却羡夷陵旧判官。"]},{"t":"过铅山有怀韩介之 其一","f":"七言绝句","c":["掩乱溪云感我思，鹅湖山下雨来时。","九原一去无消息，何处逢人问介之。"]},{"t":"过铅山有怀韩介之 其二","f":"七言绝句","c":["行行乌桕傍江湄，曾记当年共步时。","欲识九崖超拔处，盛年坚谢一官微。"]},{"t":"舟次浔阳","f":"七言律诗","c":["景物新归眼界中，浔阳城下倚孤篷。","不愁馆吏轻人客，自有庐山作主翁。","江潦欲浮东上月，蒲帆争趁北来风。","琵琶懒话当年别，拟向濂溪觅旧宗。"]},{"t":"游赤壁","f":"七言律诗","c":["平生赤壁慕黄州，梦想坡翁一夕游。","老眼欲穷今日兴，西风吹动满江秋。","山川未称文章妙，糟粕空令画笔求。","望断英雄横槊处，楚云汀树思悠悠。"]},{"t":"寓武昌宪台 其一","f":"七言律诗","c":["危然三日坐蓬壶，十览分明尽楚都。","千里云山来几席，万家烟火傍江湖。","情浓小放吾诗笔，天远长开此画图。","觅记高台无一字，先生真个是迂儒。"]},{"t":"寓武昌宪台 其二","f":"七言律诗","c":["人间何处有蓬壶，老眼西来又北都。","已觉江山雄大楚，懒将花柳话西湖。","夕阳红处添计料，南斗低时数象图。","多谢乌台今夜月，清光犹复照吾儒。"]},{"t":"将登黄鹤楼","f":"七言律诗","c":["此楼胜概传今古，此日须谁共一登。","秋气转清山自好，篇诗欲赋我何能。","眼前绝景应相候，梦里危栏久已凭。","樽酒倘逢仙子约，西风双鬓任鬅鬙。"]},{"t":"登黄鹤楼","f":"七言律诗","c":["危楼千尺势嵯峨，黄鹤仙翁旧此过。","铁笛横时江水阔，夕阳红处楚山多。","汉阳树带前朝色，鹦鹉洲添粤客歌。","倚遍栏杆无一语，白云秋色满苍波。"]},{"t":"题五殿下棠梨三喜扇面","f":"七言绝句","c":["人间何处可忘情，三喜飞来共一声。","莫道时禽无意趣，棠梨枝上祝皇明。"]},{"t":"登黄鹤楼用崔灏韵","f":"七言律诗","c":["仙乘黄鹤去千秋，观壮湖南是此楼。","山势北来青个个，江流东去碧悠悠。","云随过雁离城市，帆带斜阳傍蓼洲。","南望乡关归未得，白头应动倚门愁。"]},{"t":"湖广试院阅卷次刘宪长韵","f":"七言律诗","c":["滥持文柄屡宵兴，每倩中秋月作灯。","匣里谁将龙剑拂，斗间时见瑞光腾。","寻常肉眼终何补，僻寂心潭祇自澄。","翘首凤凰山下路，笑看仙侣尽飞升。"]},{"t":"慎庵殿下招饮次提学宪副沈中律韵","f":"七言律诗","c":["喜遇王孙笑口开，又将双眼洗黄埃。","紫霞杯向三秋酌，茉莉香从百粤来。","山拱朱门成伟观，天生护国总奇才。","风光满座催萸菊，一会斯文岂偶哉。"]},{"t":"重九日登洪山寺","f":"七言律诗","c":["怪石牙牙佛塔孤，肩舆一笑出城隅。","谁家重九堪看菊，此日洪山却爱予。","返照千林醒醉眼，秋光万顷对南湖。","悠然未尽登临兴，更览青华逸老居。"]},{"t":"访庄定山先生","f":"七言律诗","c":["面面青山面面佳，人间何处觅仙家。","身閒尽日无多事，天与双泉灌万花。","自在枕边啼谷鸟，逍遥亭子落烟霞。","我来未敢挥狂笔，坐看冬梅到日斜。"]},{"t":"喜平湖三子领乡荐兼策诸生","f":"七言律诗","c":["陆淞发解上青云，沈炼吴绅素出群。","天下何尝无吉士，老夫端亦贺斯文。","三元偶尔还遭际，一贯从来不易闻。","分付平湖诸后进，年光遮莫蹉毫分。"]},{"t":"仙居学关文","f":"七言律诗","c":["仙人居士颇搜奇，关子移来乞挽诗。","哀死吊生情合称，吟风弄月我何辞。","江山总落閒人手，文字空传太史碑。","三尺孤坟在何处，軥辀声里草离离。"]},{"t":"凤沱别业为蹇判舟","f":"七言律诗","c":["何处泷冈索旧碑，凤沱仙景我能知。","好山满眼分重庆，活水频年灌谢池。","月在梧桐村酿熟，春催布谷稻苗肥。","主人每有西归念，识破浮生几局棋。"]},{"t":"次韵朱太古太尹述怀兼致赠别之意","f":"七言律诗","c":["禄仕何能不厚颜，千金难买是身閒。","浮生莫问妻孥计，华发先催案牍间。","花县春杯犹满引，剑江魂梦已飞还。","竹村门巷桑麻长，我亦能来一扣关。"]},{"t":"送柳贰尹","f":"七言绝句","c":["利名真个有危机，箫鼓频催少府归。","莫道南川无意绪，赠行诗卷也留题。"]},{"t":"奉提学广川吴先生试赋此求教","f":"七言律诗","c":["化雨初沾万物滋，人间秋暑正炎时。","微官伎俩知无取，半百行藏每自疑。","两浙斯文端有托，西川夫子到何迟。","试看光霁难言处，桃李枝头绿渐肥。"]},{"t":"问月楼","f":"七言律诗","c":["团团壶峤月高时，笑倚东楼一问之。","精魄本来无欠缺，神光何事有盈亏。","每凭杯酒传深意，更著诗篇扣大疑。","万古升沈看未了，不知造化主张谁。"]},{"t":"梯云楼","f":"七言律诗","c":["耸压西林势渐高，诸峰眼见似儿曹。","天阶缓步何愁到，诗眼宽来不尚豪。","黄石村庄添伟观，壶公山景自周遭。","主人头白归来日，宵汉联翩数凤毛。"]},{"t":"赏中秋月","f":"七言律诗","c":["独怜庚戌中秋月，还照平湖酒一杯。","烂熳宁辞今夕醉，清光如见故人来。","平分秋色真堪赏，缓转冰轮不用催。","高步能忘扳桂念，不知丹桂是谁栽。"]},{"t":"阅事有感","f":"七言律诗","c":["桃溪李径绿参差，争妒南枝胜北枝。","抱瓮疲来空自笑，栽花老去欲成痴。","人逢利害偏堪识，俗到浇漓不受医。","留取一樽延寿酒，秋风黄菊在东篱。"]},{"t":"重九日","f":"七言律诗","c":["重阳风致落谁家，晚雨疏疏点物华。","粤客能无泉石兴，陈山虚耸海天涯。","诗眸自合评秋色，篱菊何为未放花。","最爱碧空云尽后，月明香荐木犀茶。"]},{"t":"有乡僧自钱塘来访诗以赠之","f":"七言律诗","c":["万种尘缘坐未消，山僧何处觅根苗。","消磨日月惟林谷，斟酌乾坤看斗杓。","尺帻尚堪韬黑发，夷途终见悟清宵。","欲知吾道难言妙，试向虞廷听凤韶。"]},{"t":"送沈刚夫偕吴绅赴南监七首 其一","f":"七言绝句","c":["霏霏烟气散还遮，把酒当湖认港汊。","忽忆去年今夜月，卧林亭下看梅花。"]},{"t":"送沈刚夫偕吴绅赴南监七首 其二","f":"七言绝句","c":["国子师模遇好官，抠趋休厌一冬寒。","春秋本是吾儒业，莫遣人将异类看。"]},{"t":"送沈刚夫偕吴绅赴南监七首 其三","f":"七言绝句","c":["浅倾苏合香丸酒，细咏南川老子诗。","小雨寒江难进步，留君须到大晴时。"]},{"t":"送沈刚夫偕吴绅赴南监七首 其四","f":"七言绝句","c":["浮生岁月易消磨，岁月官阶积贵多。","惟问上元程主簿，官阶资级昔如何。"]},{"t":"送沈刚夫偕吴绅赴南监七首 其五","f":"七言绝句","c":["烂熟思来寝已安，白头那厌一毡寒。","送君翻有留君意，更把长江仔细看。"]},{"t":"送沈刚夫偕吴绅赴南监七首 其六","f":"七言绝句","c":["兴尽床头草当茵，坐来还有一腔春。","乾坤不朽儿男事，懒把斯言嘱别人。"]},{"t":"送沈刚夫偕吴绅赴南监七首 其七","f":"七言绝句","c":["浦子城边几日程，送君南望不胜情。","逢人欲问栽花事，祇恐希夷睡未醒。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其一","f":"七言律诗","c":["拈弄风情老更佳，恍然珍宝落贫家。","沉吟三百头蒙被，烂慢经旬烛吐花。","脱换苏黄凌鲍谢，绝除烟火总云霞。","茫然翘首湖天晚，月子初生一片斜。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其二","f":"七言律诗","c":["奇书正正复斜斜，惊雁群飞逐晚霞。","老眼何时忘北斗，东风今夜到梅花。","舞低坛杏三更月，传及东吴几百家。","莫道南川知味浅，天然风味果然佳。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其三","f":"七言律诗","c":["源泉那似定山佳，学种平湖十里花。","天地何尝无雨露，春风原不择贫家。","诗篇到老贪明月，酒盏寻常酌晚霞。","谁谓卑官无好况，风前乌帽几回斜。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其四","f":"七言律诗","c":["僧传仙子酌流霞，颇识天厨酒味佳。","风翮忽罹尘世网，梦魂空绕榄山花。","还将双眼窥千古，却怪浮言乱百家。","何日与公重握手，中宵閒看斗杓斜。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其五","f":"七言律诗","c":["一环青带九溪斜，小小当湖景亦佳。","云影天光千万状，夕阳茅屋两三家。","桔槔尽日分来派，坛杏何年始放花。","痴坐东吴毡任冷，春风留得脸边霞。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其六","f":"七言律诗","c":["乾坤何处不堪家，欲买当湖十里霞。","阴剥阳回看硕果，朝开暮落总浮花。","湖分震泽流还止，山到东吴小亦佳。","安得孤峰青插汉，西来看尽一江斜。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其七","f":"七言律诗","c":["官冷偏赢一睡佳，浪移双脚到谁家。","木棉被拥三更后，宝鸭香消一线斜。","易透真源惟月夜，难描生意是春花。","思君却有无穷话，书破东吴十幅霞。"]},{"t":"承庄定山和答过访之作七律再用前韵寄意八首 其八","f":"七言律诗","c":["少拈诗笔少栽花，静养天根策最佳。","腔手恢恢閒贮月，童颜盎盎自生霞。","寻常世总谈斯道，千百年来得几家。","笑捧公诗无以报，腊梅聊开一枝斜。"]},{"t":"侍御彭宪卿出示过处州次却金亭韵一绝依韵奉答","f":"七言绝句","c":["沈香曾见一亭孤，何处东莱又此夫。","影响前头觑未破，敢论天宇半尘无。"]},{"t":"代柬答吴方伯","f":"七言律诗","c":["星芒垂戒向天津，仁爱天心见十分。","唐介偶谐文彦博，汉昭终辨霍将军。","心悬南极看珠斗，目断青山隔暮云。","风景八壶堪日醉，为君聊寄一慇勤。"]},{"t":"挽张佥宪父","f":"七言律诗","c":["白杨何处送残悲，挽笔狂挥又不辞。","迹灭彭城哀此老，风观西浙羡谁儿。","鸾章旧匣存封贲，杯饭比邻起梦思。","戏马台前千古月，知他留照几人碑。"]},{"t":"连珠池诸生欲搆亭其上诗以促之","f":"七言律诗","c":["池边何处着吟窝，春意催青已满莎。","接木栽花成活汁，五风十雨自中和。","子由刚被东轩笑，欧九其如画舫何。","好事几人真喝采，酒杯应不误烟波。"]},{"t":"连珠池旁与屠大理酌别","f":"五言律诗","c":["连珠池内水，照见别离心。","且酌当湖酒，聊歌粤客吟。","春花时欲暮，庭草意中深。","话柄添今日，龙门迹未沈。"]},{"t":"静观亭抛梁","f":"七言律诗","c":["亭子抛梁亦与诗，东西南北正相宜。","乾坤剩有三春意，花鸟那容一老私。","洒洒东吴新样制，殷勤多士见心知。","尘埃催得人头白，点也何拘不浴沂。"]},{"t":"哭舍弟克明三首 其一","f":"五言律诗","c":["滴尽他乡泪，愁云惨不舒。","书来刚阅月，死别忽冥途。","心苦空缘梦，天高何处呼。","无情花底月，衰影照来孤。"]},{"t":"哭舍弟克明三首 其二","f":"五言律诗","c":["欲报生前信，泉台莫寄声。","江湖千点泪，兄弟百年情。","义重哀难遣，愁多梦不成。","何时麦家径，归奠尔佳城。"]},{"t":"哭舍弟克明三首 其三","f":"五言律诗","c":["衰年催我老，右肘屡风麻。","短景那能久，浮生未有涯。","春风怀寸草，暮雨损荆花。","儿辈那堪倚，狂涂纸上鸦。"]},{"t":"静观亭雨中","f":"七言律诗","c":["风雨潇潇坐一亭，凝香寂寞对遗径。","燕鸠结舌频窥树，兰蕙藏春不放馨。","活水游鱼偏自得，满庭芳草为谁青。","凭栏更有难言意，淡淡波光著数萍。"]},{"t":"重泛当湖四首 其一","f":"五言律诗","c":["当湖宽积雨，天霁忽来游。","风荡渔舟舞，波翻旭日浮。","溪花红蘸水，岸竹冷含秋。","回棹依菰渚，深杯送急流。"]},{"t":"重泛当湖四首 其二","f":"五言律诗","c":["新水豁空碧，薰风催旧游。","草青平野合，云尽远山浮。","荷荡盘中露，波摇镜面秋。","橹声休聒耳，自在坐安流。"]},{"t":"重泛当湖四首 其三","f":"五言律诗","c":["折柬来何处，招邀事胜游。","闲情追范蠡，远意属罗浮。","桂酒三吴味，蒲风五月秋。","颓然供一醉，万物与同流。"]},{"t":"重泛当湖四首 其四","f":"五言律诗","c":["移船穿竹外，傍藻看鱼游。","雨足川源满，天青物色浮。","波扬千顷雪，山露一痕秋。","淫潦休伤稼，三农泪欲流。"]},{"t":"避暑","f":"七言律诗","c":["火云亭午欲销金，一枕移来傍绿阴。","蕲竹簟铺松榻矮，池荷香泛水波深。","犬垂倦舌眠幽草，蝉带新声过远林。","我有閒情向谁写，无言空看壁间琴。"]},{"t":"偶书","f":"七言绝句","c":["遗编三绝十年馀，俯仰乾坤只自如。","何处更逢人愤悱，且将诗句写心图。"]},{"t":"题林大参讷斋","f":"七言律诗","c":["辩捷谁能不丧真，斋头一字当书绅。","坐忘直欲方前哲，辞寡由来是吉人。","静掩虚窗闻百舌，閒搔短发对灵椿。","佩韦多少藩参意，风景闽南入梦频。"]},{"t":"寄林待用宪长三首 其一","f":"五言绝句","c":["微风动池波，片月来相照。","悠然南斗间，寂寞展清眺。"]},{"t":"寄林待用宪长三首 其二","f":"五言绝句","c":["采采青荷盘，吸此中秋露。","滴露入诗杯，离情不堪赋。"]},{"t":"寄林待用宪长三首 其三","f":"五言绝句","c":["池水涵清风，鱼儿散还聚。","安得意中人，边池纵幽别。"]},{"t":"冬官林居鲁谢病归养来访平湖赋此赠别","f":"七言律诗","c":["清秋归棹舣江浔，何事莼鲈忽上心。","风雨花枝聊共惜，云霞杯酒向谁斟。","行藏在我求无忝，道义如君契亦深。","舞罢斑斓真自得，乾坤应不乏知音。"]},{"t":"静观亭奉饯屠元勋少大理","f":"七言律诗","c":["搆亭新著静观名，别酒逢君两度倾。","鱼鸟自循飞跃性，湖山应识滞留情。","花知爱客偏含笑，蝉为催诗巧送声。","醉墨淋漓吾合赋，汉徵廷尉岂徒行。"]},{"t":"送诸生往杭州时吴提学檄选诸生听讲三首 其一","f":"七言绝句","c":["燕语莺啼又半年，金针绣手问谁传。","扁舟试向西湖去，画本烟云别有天。"]},{"t":"送诸生往杭州时吴提学檄选诸生听讲三首 其二","f":"七言绝句","c":["坠绪茫茫五百年，古人糟粕古来传。","静观坐我池亭上，鱼跃鸢飞镜里天。"]},{"t":"送诸生往杭州时吴提学檄选诸生听讲三首 其三","f":"七言绝句","c":["无言夫子教当年，不道无言是妙传。","千古路头须问讯，浮云消尽见青天。"]},{"t":"牡丹忽枯悴","f":"五言律诗","c":["此地空苔砌，谁家绚早春。","始知花富贵，亦厌我清贫。","恩育乾坤大，荣枯梦幻频。","岁寒松竹在，试为问花神。"]},{"t":"重九日三首 其一","f":"七言律诗","c":["自笑官閒岁月忙，西风吹过七重阳。","衰颜每愧逢佳节，黄菊何曾负此觞。","乡思暗随飞雁远，诗怀清浸碧波光。","春花又逐秋花发，造化凭谁作主张。"]},{"t":"重九日三首 其二","f":"七言律诗","c":["扰扰浮生空自忙，一杯谁不负重阳。","芙蓉且莫嗔篱菊，琥珀从教泛羽觞。","池水三珠含晚照，秋林一带弄晴光。","天机眼底无穷妙，织就云霞锦数张。"]},{"t":"重九日三首 其三","f":"七言律诗","c":["云边飞雁去何忙，小剥重阴别有阳。","谩把新诗催晚菊，笑携诸子引流觞。","风回舞燕窥秋色，萍散游鱼戏日光。","坐我閒亭无一语，歌人何处忽声张。"]},{"t":"何子完来访平湖用白沙封子完庐墓卷韵赠别","f":"七言律诗","c":["七年弄影笑何功，握手逢君又孟冬。","诗味直从江浦醉，墨痕须固玉台封。","休疑美玉栖顽璞，几见繁花舞乱风。","坐我池亭看镜水，白云何处觅高峰。"]},{"t":"承柳郡侯檄请修郡志过庆嘉亭赋此辞谢二首 其一","f":"七言律诗","c":["强随郡檄走嘉兴，外史才华本未能。","文献一邦公合主，是非千载我何凭。","昌黎史札还堪信，柳子龙门岂易登。","多少镇嘉山上景，许携冬酒醉瞢腾。"]},{"t":"承柳郡侯檄请修郡志过庆嘉亭赋此辞谢二首 其二","f":"七言律诗","c":["转盼人间几废兴，惟将故纸别贤能。","乾坤直笔应难秉，当贵浮云未足凭。","槜李风光深此会，庆嘉亭子幸容登。","砚池几欲挥风雨，满壁蛟龙任舞腾。"]},{"t":"镇嘉山 其一","f":"五言律诗","c":["五老攒庐阜，三洲隐薜萝。","云霞深晚树，径路入青莎。","异兽雄如斗，群仙舞欲歌。","人间天上景，会意岂须多。"]},{"t":"镇嘉山 其二","f":"五言律诗","c":["迟迟醒醉眼，稍稍傍烟萝。","曝背看拳石，开樽藉短莎。","崆峒人到少，松桧鸟长歌。","杯酒忘宾主，悠然得亦多。"]},{"t":"观山四首 其一","f":"七言绝句","c":["山在烟霞景在诗，神施鬼设可胜奇。","蓬莱飞落宫墙内，祇恐人间也未知。"]},{"t":"观山四首 其二","f":"七言绝句","c":["拨破红尘透此关，天机落在片言间。","也知虚费閒心力，争似抬头一看山。"]},{"t":"观山四首 其三","f":"七言绝句","c":["宛转虚岸纵步时，一回着目一沈思。","阿谁解领吾人意，却有黄花在短篱。"]},{"t":"观山四首 其四","f":"七言绝句","c":["冥鸿声落海天微，何事鹪鹩恋一枝。","昨夜寒霜催落叶，看山吾且一题诗。"]},{"t":"题石棋盘","f":"七言绝句","c":["人间胜负几盘棋，袖手旁观着每迟。","留得石枰方一片，不安棋子也相宜。"]},{"t":"泛鸳鸯湖二首 其一","f":"七言绝句","c":["童冠相随弄碧漪，玻璃十顷画船移。","那知今日鸳湖水，亦与吾人作酒卮。"]},{"t":"泛鸳鸯湖二首 其二","f":"七言绝句","c":["爱人冬日暖如春，凫雁相忘镜水滨。","细浪轻风催晚醉，中流一笑任吾真。"]},{"t":"书杨藩宗郡侯事","f":"七言绝句","c":["走卒儿童口是碑，六书吾岂厌烦辞。","翻疑槜李多豪杰，尚欠杨公血食祠。"]},{"t":"嘉兴郡斋与冯宪副兰柳郡侯琰小酌联句三首 其一","f":"七言律诗","c":["老眼苍茫醉欲花，海东高士忽临嘉。","云深晚雨催长句，日远骚坛愧大家。","墙角倚寒梅正萼，樽前留赋脸初霞。","分明坐我春风里，此意何妨日易斜。"]},{"t":"嘉兴郡斋与冯宪副兰柳郡侯琰小酌联句三首 其二","f":"七言律诗","c":["雪意漫空欲散花，山园松桧可胜嘉。","高风合著滁州守，美句犹传杜老家。","真率杯中深夜话，风流胸次淡秋霞。","乡书忽度湖天雁，嘹唳冲寒几字斜。"]},{"t":"嘉兴郡斋与冯宪副兰柳郡侯琰小酌联句三首 其三","f":"七言律诗","c":["夜雨松窗对烛花，便无山水亦情嘉。","疏才此地惭为郡，老句如公是作家。","再咏凫翳从岁晚，独抛尘土卧烟霞。","升沈已破浮生梦，一榻寒歌瘦竹斜。"]},{"t":"一柳双莺与冯柳二公联句","f":"七言古诗","c":["柳州堂上画图新，摩诘诗中为写真。","老眼暂看心欲醉，高怀相对咏何频。","想当落笔风情别，幸得开樽物意春。","烟雨十枝初入柳，江天双鸟最宜人。","偶来并坐空矰弋，忽著高飞远俗尘。","淑气谩催回百啭，閒情容与转相亲。","碧云声落千门晓，别墅巢深万树匀。","淡墨依稀何处得，李生往事与谁陈。"]},{"t":"郡斋夜坐与冯柳工公联句有怀屠少卿","f":"七言古诗","c":["青霄一别动经年，诗卷犹传旧咏篇。","共拨红炉看醉墨，坐销孤独费吟笺。","江湖风雪怀人远，歧路音书别思悬。","春意省中千柳直，梦回阙下五云连。","法星此夜昭河汉，驷马他年耀市廛。","伐木再歌秋鬓短，停云独立越江偏。","涓埃无补惭予老，鼎鼐能调羡子贤。","何处风光还握手，几人恩宠似登仙。","未逢驿使梅孤发，应念亲庭草自妍。","南极未应虚梦想，白头长见彩衣翩。"]},{"t":"谒陆宣公祠有感","f":"七言律诗","c":["尘埃不放庙门扃，唐相忠魂恐未宁。","孤月此心应自照，空阶碧草为谁青。","经纶一代须王佐，艰阻千年仰景星。","莫道障魔消未尽，祠前今复餂延龄。"]},{"t":"赠萧天章还荆州","f":"七言律诗","c":["短轴淋漓洒墨香，春风一笑问萧郎。","莺花尽日催人醉，客子扁舟底事忙。","眼界东来吴海阔，梦魂西绕楚江长。","行边莫厌归装薄，也有吾诗在锦囊。"]},{"t":"访当湖书屋","f":"七言律诗","c":["小结当湖屋数椽，肩舆一扣水云边。","园林花卉开天趣，伯仲书声韵管弦。","旋罩溪鱼供晚酌，坐看湖艇破秋烟。","深怀取次占巢鹊，扶醉归来踏夜船。"]},{"t":"将游陈山三首 其一","f":"五言律诗","c":["八载官垂满，三春花又深。","人偏多系累，天未定晴阴。","越海频飞梦，龙湫拟洗心。","传诗订佳侣，谁谓少知音。"]},{"t":"将游陈山三首 其二","f":"五言律诗","c":["逸少谈岷岭，平生负一游。","东吴山更少，我辈愿何酬。","僻地栖成懒，馀生习易浮。","古今言脱屣，谁复步瀛洲。"]},{"t":"将游陈山三首 其三","f":"五言律诗","c":["看山劳作梦，细雨果今晨。","诗思空泉涌，狂心自鸟驯。","盘蛇先洗石，龙母信通神。","暗惜繁花落，春光过七分。"]},{"t":"承庄定山先生垂访平湖喜而有作","f":"七言律诗","c":["新水湖天注活流，欢迎千里访医舟。","江山风韵诗全别，骨肉斯文话素投。","喜洽禽鱼俱欲舞，情亲花木也扳留。","从来乐地因人胜，一景须君一喝酬。"]},{"t":"题画","f":"五言绝句","c":["涧水清何极，山云本自深。","苑亭终日坐，谁识此翁心。"]},{"t":"次韵定山游南寺","f":"七言绝句","c":["老树交加荫小舟，数声啼鸟寺门幽。","湖山此日无穷意，都付先生一倚楼。"]},{"t":"题藏有源静学卷","f":"七言绝句","c":["鸢鱼在在领天机，恍惚虚亭独坐时。","何处湖山真托迹，晚风凉□□□□。"]},{"t":"定山来访再赠","f":"七言律诗","c":["倚棹飘然退急流，真成天地一虚舟。","春风满座人何厌，元酒开樽辖再投。","花鸟共催诸子醉，湖山增重几诗留。","荷衣舞烂梧桐叶，八载东吴愿始酬。"]},{"t":"静观亭次定山韵三首 其一","f":"五言绝句","c":["地僻人来少，春回花自深。","风光拈不尽，一物一天心。"]},{"t":"静观亭次定山韵三首 其二","f":"五言绝句","c":["岸帻虚亭晚，林风一洒然。","微酡诗懒赋，寂寞对湖天。"]},{"t":"静观亭次定山韵三首 其三","f":"五言绝句","c":["水月来相照，双眸老更清。","人间无限事，吾且坐吾亭。"]},{"t":"赏牡丹","f":"七言律诗","c":["春风何处不繁华，宦况萧条愧此花。","暖日烘来娇欲语，淡烟霏处醉笼纱。","生成只见天机妙，吟赏翻疑酒量加。","诸老洛阳题品后，风光今日又谁家。"]},{"t":"渡江二首 其一","f":"七言律诗","c":["潮声汹涌傍山眉，万里江流海吸之。","两眼未谙风节候，片帆低挂日中时。","云藏瓜步偏疑画，景会金山忽有诗。","衡鉴斯文能不愧，天机地轴果谁知。"]},{"t":"渡江二首 其二","f":"七言律诗","c":["八字金焦豁两眉，江中风景尽归之。","寻常过往知如今，饱饫游观是几时。","老去一官催白发，兴来千首欲留诗。","蒲帆小趁南薰力，明日阴晴未可知。"]},{"t":"登高邮湖","f":"七言绝句","c":["晨风淡淡抹湖波，水色天光一镜磨。","细柳菰蒲村客远，数声何处采莲歌。"]},{"t":"宝应湖","f":"七言绝句","c":["微茫新水涨洪波，南北行人感慨多。","何似西湖风景好，近山青拥数堆螺。"]},{"t":"游清河经黄河感而有作四首 其一","f":"七言绝句","c":["黄河之水入清河，滚滚浑成一样波。","评注水经推陆羽，试分清浊果谁多。"]},{"t":"游清河经黄河感而有作四首 其二","f":"七言绝句","c":["云帆一片驾长波，茱黍村庄瞥眼过。","回首夕阳添泪咏，清河今已混黄河。"]},{"t":"游清河经黄河感而有作四首 其三","f":"七言绝句","c":["中天一派淡无波，海渎精华耿此过。","为报寻源高着眼，天河元不是黄河。"]},{"t":"游清河经黄河感而有作四首 其四","f":"七言绝句","c":["欲张吾网向流河，定有遗珠在碧波。","鼓枻中流情不浅，水云风景晚来多。"]},{"t":"经白洋河二首 其一","f":"七言绝句","c":["浮生踪迹笑奔波，百岁升沈梦里过。","凝望郊原意无限，晚风吟过白洋河。"]},{"t":"经白洋河二首 其二","f":"七言绝句","c":["长牵直北溯漕河，柳色青青蘸碧波。","淮酒尚堪供一醉，葛巾斜日定风多。"]},{"t":"舟中苦热","f":"七言律诗","c":["两耳何堪近俗哗，急流牵溯几湾斜。","孤舟亭午蒸炎暑，崩岸回风落细沙。","堤柳浓阴空著日，星河深夜忆浮槎。","琼浆满口浇诗渴，谢得邳州一片瓜。"]},{"t":"沙河道中","f":"七言律诗","c":["青衫何日浣黄埃，老眼于今又北开。","两脚忽从天际起，山光仍傍马前来。","乱蝉高柳临官道，古冢残碑枕土坏。","返照扬鞭意无限，暂投村店泻磁杯。"]},{"t":"伏中由沙河舍舟而陆三日至开河","f":"七言律诗","c":["水云三伏正煎熬，暑汗沾裳不谢劳。","驿路驱驰疲仆马，闸河开闭任官豪。","临棋祇恐迷当局，袖手还输不著高。","未识新蝉意何谓，绿杨阴里日呼号。"]},{"t":"漕运兵三首 其一","f":"七言绝句","c":["闸河初放鼓田田，辛苦挨帮拽几船。","惟愿漕渠春水满，任官来索赛神钱。"]},{"t":"漕运兵三首 其二","f":"七言绝句","c":["年年休叹往来频，屈指深冬又早春。","惨目寒肤归未得，三边犹有枕戈人。"]},{"t":"漕运兵三首 其三","f":"七言绝句","c":["风尘飞捲酒旗轻，尽日惟闻打号声。","自顾无钱堪买酒，夜凉交枕月华明。"]},{"t":"连窝舟中偶述四首 其一","f":"七言律诗","c":["扁舟如箭下中流，何处风烟更可留。","诗思乱撩官柳色，橹声摇碎闸河秋。","湖山有梦回青眼，岁月无情易白头。","北往南来觑未破，人间富贵是云浮。"]},{"t":"连窝舟中偶述四首 其二","f":"七言律诗","c":["韶光去我疾如流，费尽诗辞莫挽留。","袍葛未离三伏暑，雁声遥送一天秋。","还凭白月开心曲，懒把焦桐上指头。","惨目风烟醒复醉，铁桥高步忆罗浮。"]},{"t":"连窝舟中偶述四首 其三","f":"七言律诗","c":["推移何日到安流，笑把新题处处留。","舒卷未谙周卦画，支离空抱鲁春秋。","閒将醉墨开醒眼，宽着乌纱裹白头。","泡沫风灯容顾惜，此身天地任沈浮。"]},{"t":"连窝舟中偶述四首 其四","f":"七言律诗","c":["慈闱飞梦泪交流，苦被微官久绊留。","玉食谁为天下计，斯文聊寄眼中秋。","黄花准拟供南酒，白发相将遍黑头。","半醉半醒吾欲赋，柳风吹动野烟浮。"]},{"t":"铜鼓二首 其一","f":"七言绝句","c":["铜鼓鼕鼕聒耳频，世机纷扰正愁人。","官夫又拨民夫辏，剥尽衣衫哭水滨。"]},{"t":"铜鼓二首 其二","f":"七言绝句","c":["铜鼓扶胥旧饱闻，数声催转海门春。","闸河处处闻铜鼓，愁杀夫差忍饿人。"]},{"t":"京口","f":"七言律诗","c":["羞傍双眉著片纱，鞭羸无计避尘沙。","秋风渐扫人间暑，老眼徐看帝里花。","山水周遭留玉气，楼台缥缈出烟霞。","观光我有无穷意，且放幪头破帽斜。"]},{"t":"寓京兆北堂将赴试院用旧韵呈诸同事四首 其一","f":"七言律诗","c":["不为斯文浪皱眉，鉴空毫发莫欺之。","谁从混沌开端倪，颇学支离到此时。","风雅未回中古制，仆臣羞对晚唐诗。","诸君道眼相料理，何事还堪答所知。"]},{"t":"寓京兆北堂将赴试院用旧韵呈诸同事四首 其二","f":"七言律诗","c":["断隔尘沙不上眉，一堂高坐更何之。","閒同释子安禅日，静到希夷闭閤时。","阅世且留双眼孔，遣怀添得几篇诗。","平生坎止流行意，怕有清秋白月知。"]},{"t":"寓京兆北堂将赴试院用旧韵呈诸同事四首 其三","f":"七言律诗","c":["天闲十二近山眉，骏骨吾将一顾之。","大府虚堂淹此日，白云高帽去何时。","文衡有旨惭公剡，秋兴无端寄小诗。","聚首传杯休谢醉，酒中真味少人知。"]},{"t":"寓京兆北堂将赴试院用旧韵呈诸同事四首 其四","f":"七言律诗","c":["不学娉婷老画眉，小拈枯笔亦羲之。","斯文衡鉴聊今日，平地风云笑此时。","观国未忘心里易，绿衣閒咏意中诗。","如何一觉蒙头睡，祇有图南老子知。"]},{"t":"寓京兆府闻宁永贞别驾因问","f":"七言律诗","c":["偶此逢人道讣音，吞声挥涕夜堂深。","中都亦是栖贤地，别驾空怀济世心。","老去功名真似梦，别来书问几浮沈。","长安旧识何蕃面，无限芳声在士林。"]},{"t":"试事已毕呈毕嘉会少京兆","f":"七言律诗","c":["自拜天颜入棘闱，斯文曾不乏瞻依。","从知忠信堪凭仗，何处荣华免是非。","秋月普来心里照，晨星谁道眼中稀。","提携京兆逢贤佐，未许权舆咏落晖。"]},{"t":"戏题小录","f":"七言绝句","c":["杂剧风情共一书，三年人事又乘除。","郎当舞袖谁收拾，展转寒窗愧老夫。"]},{"t":"出京舟次潞河","f":"七言律诗","c":["久速那能见事机，西风吹逐马蹄飞。","红尘十丈应饶我，绿水三秋更浣衣。","浅渚轻欧时泛泛，淡云疏柳晚依依。","漕渠湍急人争渡，閒看归樵对落晖。"]},{"t":"潞河发舟","f":"五言律诗","c":["尘埃清一雨，屈指问程期。","水急船流滑，天空鸟去迟。","寒催霜降节，兴负菊花诗。","拂袖翻然意，沙鸥恐未知。"]},{"t":"秋兴次杜工部韵八首 其一","f":"七言律诗","c":["红枣香梨缀近林，古槐高柳漫萧森。","三秋时节过重九，一画阳刚对五阴。","雁影远空绘弋计，笛声寒写别离心。","行人黑发今无几，怕遇荒村一夜砧。"]},{"t":"秋兴次杜工部韵八首 其二","f":"七言律诗","c":["霜叶红飘几树斜，西风争欲扫繁华。","持衡本是南人手，传食来乘北使槎。","母子他乡元有泪，梦魂深夜更悲笳。","摩挲莫放归程缓，老眼青山尚未花。"]},{"t":"秋兴次杜工部韵八首 其三","f":"七言律诗","c":["输赢人世几枰棋，梦破浮生我不悲。","布被温存秋睡思，鼻雷酣到日红时。","凉生玉露山偏好，瘦傍东篱菊每迟。","日饭两杯聊自足，了无閒事可寻思。"]},{"t":"秋兴次杜工部韵八首 其四","f":"七言律诗","c":["返照千秋对落晖，秋风不动晚风微。","撩人诗思那能遏，傍枕沙鸥故不飞。","宇宙千年俱可鉴，尘氛十事九相违。","李膺莫谓知机早，一箸鲈鱼脍本肥。"]},{"t":"秋兴次杜工部韵八首 其五","f":"七言律诗","c":["罗浮失却梦中山，一笛西风落世间。","丹汞未离新火候，铁桥空忆旧仙关。","画图不用描凡影，沆瀣聊将洗醉颜。","何事斯文远相绊，也随秋色到鹓班。"]},{"t":"秋兴次杜工部韵八首 其六","f":"七言律诗","c":["谈笑谁收百战功，老怀增感寂寥中。","金台未泯燕昭迹，骏骨犹传国士风。","人事秋霜催短鬓，世机绿叶变新红。","晦明因革堪先定，懒把前朝问塞翁。"]},{"t":"秋兴次杜工部韵八首 其七","f":"七言律诗","c":["不向青铜怨白头，一凉如水却宜秋。","清风明月开诗卷，紫酒黄花遣旅愁。","天际翱翔须老凤，沙边自在几眠鸥。","微酡小发行边兴，迤逦缄题寄广州。"]},{"t":"秋兴次杜工部韵八首 其八","f":"七言律诗","c":["诗寻老步更逶迤，野菊秋含十顷陂。","鸠杖冲寒扶短履，酒杯和露滴南枝。","烟浮木榻香风细，影落松梢日色移。","何处归来深闭閤，坐穷清昼一帘垂。"]},{"t":"次韵答吴居士","f":"七言律诗","c":["老去青毡不怨寒，閒将镜水静中看。","幅巾何处来斯老，西席裒然对冷官。","铅椠未嗟身计薄，烟霞聊放脚头宽。","太平八十身长健，懒逐飞尘听八鸾。"]},{"t":"得白沙先生柬","f":"七言律诗","c":["天空南斗望沈时，半幅书来慰我思。","何处烟波堪指拟，此生妻子免寒饥。","移居近洛依康节，沾禄归山愧杜诗。","谢得端溪贤别驾，雷声荐福敢多疑。"]},{"t":"和一庵赠别王廷秀","f":"五言古诗","c":["晨兴敞虚閤，何处来清吟。","悠然一读之，感慨钟吾心。","滚滚旴江流，胡为钓一任。","念昔小陂老，灭迹穷山深。","丹壁立千仞，遗踪杳难寻。","圣途千万里，暮景来骎骎。","元酒赊真味，扫杯谁与斟。","绸缪出情素，展转来予钦。","纷哉求备子，是古而非今。","太虚自廖廓，白白生层阴。","遂令幽隐士，旷代微知音。"]},{"t":"次韵姜仁夫秋官过访平湖四首 其一","f":"五言绝句","c":["细雨池亭晚，凭栏水镜宽。","西风传信息，一舸独冲寒。"]},{"t":"次韵姜仁夫秋官过访平湖四首 其二","f":"五言绝句","c":["寂静湖边水，何人此繫舟。","欢声迎夜楫，惊散几眠鸥。"]},{"t":"次韵姜仁夫秋官过访平湖四首 其三","f":"五言绝句","c":["何处桃源路，当湖也自深。","东风吹画舫，春早一相寻。"]},{"t":"次韵姜仁夫秋官过访平湖四首 其四","f":"五言绝句","c":["初更催县鼓，倒履迓仙槎。","细雨销红烛，连床语白沙。"]},{"t":"赠别姜仁夫秋官","f":"七言律诗","c":["纡迟画舫趁溪风，却喜斯文气味同。","一镜湖光杯酌里，百年心事雨声中。","疑人节候寒还暖，照眼花枝白间红。","老我孤怀如未写，更将诗白为谁工。"]},{"t":"题蕉池积雪图","f":"七言律诗","c":["长梢罗展翠云屏，会听慈山夜雨零。","何处蕉池添雪色，也留诗句落丹青。","笔端造化宜裨世，眼底风光浪肖形。","谁写西湖春气味，一枝香雪浸铜瓶。"]},{"t":"桃花四首 其一","f":"七言绝句","c":["笑倚东风醉未醒，笼烟间雨不胜情。","道人不用描真影，倒照边池水自清。"]},{"t":"桃花四首 其二","f":"七言绝句","c":["食桃唾核长桃裁，又见桃花此日开。","雨露既深还食实，不妨终岁事栽培。"]},{"t":"桃花四首 其三","f":"七言绝句","c":["一机红锦织天章，戏蝶游蜂日日忙。","坐我池边诗懒赋，只将杯酒对斜阳。"]},{"t":"桃花四首 其四","f":"七言绝句","c":["桃花初放柳丝丝，傍柳看桃履屡移。","淑气熏人浓似醉，隔花啼鸟忽催诗。"]},{"t":"对紫荆花有怀亡弟克明","f":"七言绝句","c":["花开花落太无情，春信何缘到紫荆。","梦断重泉挥老泪，人间时节又清明。"]},{"t":"癸丑三月十三日刘生玘邀为陈山之游以事不果赋此呈胡伯雍明府二首 其一","f":"七言律诗","c":["浪说陈山已九年，陈山何事久无缘。","莺花未远清明节，云水谁撑乍浦船。","越海且留双眼孔，龙湫欲试一名泉。","多情却被无情误，笑听东风怨杜鹃。"]},{"t":"癸丑三月十三日刘生玘邀为陈山之游以事不果赋此呈胡伯雍明府二首 其二","f":"七言律诗","c":["弄影浮沈过几年，障魔应未了尘缘。","空留乍浦看山眼，误却当湖载酒船。","平地风波翻越海，通宵牛斗照龙泉。","白头工部真何意，颠倒诗辞咏杜鹃。"]},{"t":"宿陈山时陪胡伯雍明府祭神龙","f":"七言律诗","c":["碑残寺古不知年，懒向山僧话夙缘。","杯酒未忘心里景，春风来放画中船。","神龙巧送深更雨，天籁如闻绝壑泉。","丰乐预占明府赐，天津何敢乱啼鹃。"]},{"t":"游陈山遇雨","f":"七言律诗","c":["轧轧肩舆冒晓寒，霏微空翠湿层峦。","山经宿雨偏堪爱，树带飞云更耐看。","睥睨西环城廓小，烟波南去海天宽。","阴晴未定天公意，错讶神龙洗酒坛。"]},{"t":"雨霁复登陈山","f":"七言律诗","c":["宿雨初收露气寒，又移双履出层峦。","三回命驾俱成误，几点青山可易看。","杯酒笑谈春意远，潮声吞吐海门宽。","巉岩历尽扶鸠杖，招手何人入社坛。"]},{"t":"游陈山议搆亭龙湫之上二首 其一","f":"七言律诗","c":["晚风占得勃鸠灵，又理肩舆及晓星。","九点青山凝夙露，百年双眼寄沧溟。","林花处处俱含笑，卯酒腾腾尚未醒。","几酌龙湫清到骨，是谁来搆插云亭。"]},{"t":"游陈山议搆亭龙湫之上二首 其二","f":"七言律诗","c":["淑气偏钟海岳灵，吴山几点落晨星。","巉岩缓步轻千仞，浩荡于今识八溟。","渺渺烟云诗里画，陶陶春酒醉中醒。","当湖多少閒风景，不为龙湫著一亭。"]},{"t":"赏牡丹二首 其一","f":"七言律诗","c":["万事都教落酒卮，东风又遇牡丹期。","深春花样殊无匹，割手金杯且莫辞。","造化源头观邵子，翠云丛处舞西施。","天机巧妙谁收拾，写入南川几句诗。"]},{"t":"赏牡丹二首 其二","f":"七言律诗","c":["洛阳城里聚金卮，数百年来负赏期。","谷雨节催花正好，静观亭下醉何辞。","天然绝品难描画，造化凭谁为设施。","一咏一觞看未厌，尧夫添得打乖诗。"]},{"t":"龙湫","f":"五言古诗","c":["侵晓凌巅崖，长风扫阴晦。","龙湫仅盈尺，脉透千丈内。","潜流出峎崿，淑气罩烟霭。","源深却露浅，极小能藏大。","层峦势初止，断石巧相对。","洞门掩龙宫，石罅浮漦濑。","翻凝海势雄，喷漱山骨碎。","砱砻不可遏，气透青嶂外。","泡沫隐天灵，禋祀来旌旆。","深源杳难穷，远窦接馀籁。","灵踪今几时，幽赏发我辈。","洞然虚谷中，一叩了无碍。","苏枯济旱功，且看风云会。"]},{"t":"与处州吴千兵索金盘露","f":"七言律诗","c":["磁瓶千里贮琼浆，一滴金盘露未尝。","杨柳风偏吹醒眼，牡丹花不入愁肠。","閒吟莫助诗怀壮，静坐宁须舞袖长。","春景满前催晚醉，大书吾笑为谁忙。"]},{"t":"题扇面 其一","f":"七言绝句","c":["两岸芦花夹钓舟，轻风不动水光浮。","主人已醉金盘露，閒坐船头看白鸥。"]},{"t":"题扇面 其二","f":"七言绝句","c":["掷下长竿及短蓑，又将横笛弄烟波。","竹枝声断雁飞去，不奈江天好景何。"]},{"t":"义搆陈山龙湫亭","f":"七言律诗","c":["泉亭花鸟预相催，老眼看船更几回。","斗水冷清涵日月，白龙变化有风雷。","游人到处添诗话，胜事逢谁笑口开。","我本爱山山爱我，不辞重扫白云堆。"]},{"t":"题当湖别意二首 其一","f":"七言律诗","c":["掷下磁杯对绿阴，雨添新碧为谁深。","宁知满镜当湖水，不照离人此日心。","杳杳醉乡收别泪，齁齁睡息带吴音。","婆娑莫怨归期早，云在青山鸟在林。"]},{"t":"题当湖别意二首 其二","f":"七言律诗","c":["白发愁惊几簿书，归途今已谢迷途。","且看诗笔难描景，也入当湖送别图。","万事到头俱幻梦，一杯叉手是真吾。","烟波满眼催人醉，明月飞云隔绿芜。"]},{"t":"送欧员外还京时彭从吾亚卿两浙赈济","f":"七言律诗","c":["凶年谁为变丰年，阴冷潜消浙水边。","入幕共瞻双节钺，覆盘分照几颠连。","梦魂已捧中天日，箫鼓频催入画船。","追送平生那惮远，荆州欲识愧无缘。"]},{"t":"承许宪副昌世沈大参元节过访留饮静观亭既别大参留诗示教依韵奉答","f":"七言律诗","c":["碧玉斜连水半环，一亭刚占百花间。","投壶小醉三春景，解组新逢二老间。","白雨跳珠供酒盏，黑云堆墨拥湖山。","激昂后进须先辈，不用横渠写订顽。"]},{"t":"癸丑六月之望立秋后一日胡伯雍明府邀泛当湖","f":"七言律诗","c":["烂熳当湖送酒频，移船刚占一秋新。","主宾倾倒夜初半，天水交辉月两轮。","煮茗临荷收玉露，买鲜举网见渔人。","清风两袖难言意，谁遣丹青为写真。"]},{"t":"题使浙还朝卷","f":"七言律诗","c":["送别湖山一振衣，使君曾不与心违。","竹头木屑存经济，走卒儿童识是非。","万里归心连浙水，五云深处望京畿。","画船不载江南物，却许吾诗满卷题。"]},{"t":"嘉兴柳郡侯挽","f":"七言律诗","c":["四郡翱翔鬓未侵，鸳湖忽见一星沈。","簿书未是文翁志，誉毁难移子产心。","鹤梦已随秋气化，月华空照夜堂深。","吞声我有衷情泪，不为儿孙少橐金。"]},{"t":"雪窗","f":"七言律诗","c":["此心爱雪此窗知，雪意偏容贯四时。","梅萼香飘春信早，月华光照梦醒迟。","扁舟剡曲谁乘兴，斗帐羊羔酒满卮。","莫遣尘埃侵素壁，老夫还解一题诗。"]},{"t":"给由赴杭杨玘曹魁杨燧三子在侍","f":"七言律诗","c":["癸丑人间八月秋，三生侍我又杭州。","抠趋渐了微官债，俯仰终怀实禄羞。","世味共倾今日酒，山光还记昔年游。","明朝拂袖红尘外，更买西湖一叶舟。"]},{"t":"发钱塘二首 其一","f":"五言律诗","c":["何处寻真景，湖山正夕阳。","秋波含佛塔，城市隔林塘。","衣振风回舞，帆开鸟共翔。","沿流住溪曲，舟子未须忙。"]}]};